     6	/**
     7	 * Accepts either a Firebase ID token OR an API key in the Authorization
     8	 * header — requireAuth already handles Firebase tokens; this wraps it to
     9	 * also accept `Bearer shx_...` for scripted/API access, resolving to the
    10	 * same req.user shape so every existing route works unchanged either way.
    11	 *
    12	 * API keys always resolve to role 'customer' regardless of the underlying
    13	 * user's actual role — a key is scoped to "act as this customer for their
    14	 * own resources", never a path to admin/support access even if the person
    15	 * happens to be staff.
    16	 */
    17	export async function requireAuthOrApiKey(req: AuthedRequest, res: Response, next: NextFunction) {
    18	  const header = req.headers.authorization;
    19	  if (!header?.startsWith('Bearer ')) {
    20	    return res.status(401).json({ error: 'Missing bearer token' });
    21	  }
    22	
    23	  const token = header.slice('Bearer '.length);
    24	
    25	  if (token.startsWith('shx_')) {
    26	    const keyHash = hashApiKey(token);
    27	    const apiKey = await prisma.apiKey.findUnique({ where: { keyHash }, include: { user: true } });
    28	
    29	    if (!apiKey || apiKey.revokedAt) {
    30	      return res.status(401).json({ error: 'Invalid or revoked API key' });
    31	    }
    32	
    33	    void prisma.apiKey.update({ where: { id: apiKey.id }, data: { lastUsedAt: new Date() } }).catch(() => {});
