     4	/**
     5	 * CSRF Protection Middleware using Origin header validation.
     6	 * 
     7	 * While Firebase JWT (Bearer token) inherently provides some CSRF protection
     8	 * (attackers can't steal tokens from cookies), Origin validation provides
     9	 * defense-in-depth by ensuring state-changing requests come from trusted origins.
    10	 * 
    11	 * This prevents scenarios where a malicious site makes authenticated fetch()
    12	 * requests to our API if a user is logged into the dashboard.
    13	 */
    14	
    15	const ALLOWED_ORIGINS = [
    16	  // Production domains (update these with your actual production URLs)
    17	  'https://app.shanutechx.com',
    18	  'https://shanutechx.com',
    19	  'https://www.shanutechx.com',
    20	  
    21	  // Development/local origins
    22	  'http://localhost:3000',
    23	  'http://localhost:3001',
    24	  'http://127.0.0.1:3000',
    25	];
    26	
    27	/**
    28	 * Shared origin-allowlist check, used both by this CSRF middleware (for
    29	 * state-changing requests) and by the CORS configuration in index.ts (for
    30	 * every request, including GET). Previously index.ts had its own,
    31	 * separate "reflect any Origin back with credentials: true" CORS
    32	 * middleware -- this consolidates both onto the one real allowlist
    33	 * (audit finding M1) instead of maintaining two divergent origin checks.
    34	 */
    35	export function isOriginAllowed(origin: string): boolean {
    36	  return (
    37	    ALLOWED_ORIGINS.includes(origin) ||
    38	    origin.endsWith('.shanutechx.com') ||
    39	    origin === 'https://shanutechx.com'
    40	  );
    41	}
    42	
    43	/**
    44	 * Validates Origin header for state-changing requests (POST, PUT, DELETE, PATCH).
    45	 * Read operations (GET, HEAD, OPTIONS) are allowed without origin validation.
    46	 */
    47	export function csrfProtection(req: Request, res: Response, next: NextFunction): void {
    48	  // Only validate state-changing methods
    49	  const STATE_CHANGING_METHODS = ['POST', 'PUT', 'DELETE', 'PATCH'];
    50	  
    51	  if (!STATE_CHANGING_METHODS.includes(req.method)) {
    52	    return next();
    53	  }
    54	  
    55	  const origin = req.headers.origin;
    56	  const referer = req.headers.referer;
    57	  
    58	  // If no Origin header, check Referer as fallback
    59	  // (Some older browsers or tools don't send Origin)
    60	  if (!origin && !referer) {
    61	    logger.warn(
    62	      {
    63	        method: req.method,
    64	        path: req.path,
    65	        ip: req.ip,
    66	        userAgent: req.headers['user-agent'],
    67	      },
    68	      'CSRF: No Origin or Referer header on state-changing request'
    69	    );
    70	    res.status(403).json({ 
    71	      error: 'Request origin could not be verified. Please ensure your browser allows Origin headers.' 
    72	    });
    73	    return;
    74	  }
    75	  
    76	  // Check if origin or referer matches allowed list
    77	  const requestOrigin = origin || (referer ? new URL(referer).origin : '');
    78	  
    79	  if (!isOriginAllowed(requestOrigin)) {
    80	    logger.warn(
    81	      {
    82	        method: req.method,
    83	        path: req.path,
    84	        origin: requestOrigin,
    85	        ip: req.ip,
    86	        userAgent: req.headers['user-agent'],
    87	      },
    88	      'CSRF: Blocked request from disallowed origin'
    89	    );
    90	    res.status(403).json({ 
    91	      error: 'Request origin not allowed. Cross-origin requests from this domain are not permitted.' 
    92	    });
    93	    return;
    94	  }
    95	  
    96	  // Origin validated, proceed
    97	  next();
    98	}
    99	
   100	/**
   101	 * Helper function to add custom allowed origins at runtime (e.g., for testing or dynamic domains).
   102	 * NOT recommended for production - configure ALLOWED_ORIGINS array instead.
   103	 */
   104	export function addAllowedOrigin(origin: string): void {
   105	  if (!ALLOWED_ORIGINS.includes(origin)) {
   106	    ALLOWED_ORIGINS.push(origin);
   107	    logger.info({ origin }, 'Added allowed origin for CSRF protection');
   108	  }
   109	}

