     5	export type UserRole = 'customer' | 'admin' | 'support' | 'dev';
     6	
     7	/**
     8	 * Role-Based Access Control middleware factory.
     9	 * 
    10	 * Creates a middleware function that enforces role-based access control
    11	 * for API endpoints. The middleware verifies that the authenticated user
    12	 * has one of the specified roles.
    13	 * 
    14	 * @param roles - One or more roles that are authorized to access the endpoint
    15	 * @returns Express middleware function that enforces role requirements
    16	 * 
    17	 * @example
    18	 * // Allow only admin and dev users
    19	 * router.post('/catalog', requireAuth, requireRole('admin', 'dev'), createCatalogItem);
    20	 * 
    21	 * @example
    22	 * // Allow all authenticated users (any role)
    23	 * router.get('/catalog', requireAuth, requireRole('customer', 'admin', 'support', 'dev'), getCatalog);
    24	 * 
    25	 * **Validates: Requirements 5.1, 5.2, 5.3, 5.4, 5.11, 5.12**
    26	 * 
    27	 * Authorization Rules:
    28	 * - 5.1: Only admin and dev users can create catalog items
    29	 * - 5.2: Only admin and dev users can edit catalog items
    30	 * - 5.3: Only admin and dev users can create VPS plans
    31	 * - 5.4: Only admin and dev users can edit VPS plans
    32	 * - 5.11: Admin features are hidden in the UI for customer users
    33	 * - 5.12: User roles validated at both API endpoint level and UI component level
    34	 */
    35	export function requireRole(...roles: UserRole[]) {
    36	  return (req: AuthedRequest, res: Response, next: NextFunction) => {
    37	    // Ensure user is authenticated (should be enforced by requireAuth middleware first)
    38	    if (!req.user) {
    39	      return res.status(401).json({ 
    40	        error: 'Authentication required',
    41	        message: 'You must be logged in to access this resource'
    42	      });
    43	    }
    44	
    45	    // Check if user's role is in the allowed roles list
    46	    if (!roles.includes(req.user.role)) {
    47	      return res.status(403).json({ 
    48	        error: 'Insufficient permissions',
    49	        message: `This action requires one of the following roles: ${roles.join(', ')}. Your role: ${req.user.role}`,
    50	        requiredRoles: roles,
    51	        userRole: req.user.role
    52	      });
    53	    }
    54	
    55	    // User has required role, proceed to next middleware
    56	    next();
    57	  };
    58	}
