    60	/**
    61	 * Resource ownership verification utility.
    62	 * 
    63	 * Verifies that the authenticated user owns the specified resource.
    64	 * Returns 404 (not 403) when a customer attempts to access another customer's
    65	 * resource to avoid revealing the resource's existence.
    66	 * 
    67	 * Dev bypasses ownership checks unconditionally and can access all resources.
    68	 * Admin no longer gets a blanket bypass (changed 2026 — see CLAUDE.md "Phase 15:
    69	 * Scoped Admin"): an admin can only act on a resource owned by a customer who
    70	 * is explicitly assigned to them (`User.assignedAdminId`), which the dev user
    71	 * sets via `PATCH /admin/customers/:id/assign`. This is an async check (it
    72	 * hits the DB), so use `verifyResourceOwnershipAsync` in any route handler —
    73	 * `verifyResourceOwnership` below is kept for dev/customer-only call sites
    74	 * that don't need the extra query.
    75	 * 
    76	 * @param resourceOwnerId - The ID of the user who owns the resource
    77	 * @param req - The authenticated request object
    78	 * @param res - The Express response object
    79	 * @returns true if the user has access, sends HTTP response and returns false otherwise
    80	 * 
    81	 * @example
    82	 * // In a route handler
    83	 * const deployment = await prisma.deployment.findUnique({ where: { id: deploymentId } });
    84	 * if (!deployment) {
    85	 *   return res.status(404).json({ error: 'Deployment not found' });
    86	 * }
    87	 * if (!(await verifyResourceOwnershipAsync(deployment.userId, req, res))) {
    88	 *   return; // Response already sent
    89	 * }
    90	 * 
    91	 * **Validates: Requirements 5.7, 5.8**
    92	 * 
    93	 * Authorization Rules:
    94	 * - 5.7: Customer users can only view their own deployments
    95	 * - 5.8: Customer users can only manage their own custom domains
    96	 * 
    97	 * **Security Note**: Returns 404 instead of 403 for customers accessing other
    98	 * customers' resources to prevent information disclosure about resource existence
    99	 * (Requirement 5.12 enforcement - task detail requirement).
   100	 */
   101	export function verifyResourceOwnership(
   102	  resourceOwnerId: string,
   103	  req: AuthedRequest,
   104	  res: Response
   105	): boolean {
   106	  // Only dev gets an unconditional bypass now. Admin is intentionally NOT
   107	  // checked here — admin's access is scoped to assigned customers, which
   108	  // requires a DB lookup, so admin routes must use
   109	  // verifyResourceOwnershipAsync instead. A plain 'admin' role reaching this
   110	  // function falls through to the strict self-ownership check below, which
   111	  // is the safe (deny-by-default) direction for anything not yet migrated.
   112	  if (req.user?.role === 'dev') {
   113	    return true;
   114	  }
   115	
   116	  // Check if the authenticated user owns the resource
   117	  if (req.user?.id !== resourceOwnerId) {
   118	    // Return 404 (not 403) to avoid revealing resource existence
   119	    // This satisfies the task requirement: "Return 404 (not 403) when customer 
   120	    // attempts to access other customer's resources"
   121	    res.status(404).json({ 
   122	      error: 'Resource not found',
   123	      message: 'The requested resource does not exist or you do not have access to it'
   124	    });
   125	    return false;
   126	  }
   127	
   128	  return true;
   129	}
