   131	/**
   132	 * Pure boolean version of the ownership check — no res side-effects, so
   133	 * route handlers that want their own 404/error shape (e.g. invoices.ts,
   134	 * which returns null and lets the caller decide the response) can use this
   135	 * instead of `verifyResourceOwnershipAsync`, which writes the response
   136	 * itself when access is denied.
   137	 */
   138	export async function canAccessResource(resourceOwnerId: string, req: AuthedRequest): Promise<boolean> {
   139	  if (req.user?.role === 'dev') return true;
   140	  if (req.user?.role === 'admin') {
   141	    const owner = await prisma.user?.findUnique({
   142	      where: { id: resourceOwnerId },
   143	      select: { assignedAdminId: true },
   144	    });
   145	    if (!owner) return false;
   146	    return owner.assignedAdminId === req.user.id || owner.assignedAdminId == null;
   147	  }
   148	  return req.user?.id === resourceOwnerId;
   149	}
