     2	import Redis from 'ioredis';
     3	import { env } from '../env';
     4	import { AuthedRequest } from './auth';
     5	import { logger } from '../lib/logger';
     6	
     7	// Deliberately a separate, independent ioredis client from the BullMQ
     8	// queue's connection (see lib/queue.ts's comment on why bullmq gets plain
     9	// connection options instead of an instance) — this one has nothing to do
    10	// with bullmq, so there's no version-conflict risk handing it a real
    11	// ioredis instance directly.
    12	const redis = new Redis(env.redisUrl);
    13	
    14	const TTL_SECONDS = 60 * 10; // 10 minutes — long enough to cover a retry storm, short enough not to accumulate forever
    15	
    16	interface CachedResponse {
    17	  status: number;
    18	  body: unknown;
    19	}
    20	
    21	/**
    22	 * Applied to checkout and payment-proof-upload specifically — the two
    23	 * endpoints where a double-tap or a retried request on a flaky mobile
    24	 * connection could otherwise create a duplicate order or a duplicate
    25	 * payment record. The client sends an `Idempotency-Key` header (any
    26	 * unique-per-attempt string, e.g. a UUID generated once per button press);
    27	 * a repeated request with the same key within the TTL window gets the
    28	 * original response replayed instead of re-running the handler.
    29	 *
    30	 * Scoped per-user, not just per-key — two different users could otherwise
    31	 * collide on the same key, and more importantly a leaked/guessed key
    32	 * shouldn't let someone else replay your response.
    33	 */
    34	export function idempotent(req: Request, res: Response, next: NextFunction) {
    35	  const key = req.headers['idempotency-key'];
    36	  if (typeof key !== 'string' || !key) {
    37	    return next(); // no key provided — not required, just supported
    38	  }
    39	
    40	  const userId = (req as AuthedRequest).user?.id ?? 'anonymous';
    41	  const cacheKey = `idempotency:${userId}:${req.path}:${key}`;
    42	
    43	  redis
    44	    .get(cacheKey)
    45	    .then((cached) => {
    46	      if (cached) {
    47	        const parsed: CachedResponse = JSON.parse(cached);
    48	        res.status(parsed.status).json(parsed.body);
    49	        return;
    50	      }
    51	
    52	      const originalJson = res.json.bind(res);
    53	      res.json = (body: unknown) => {
    54	        // Only cache success responses — a transient failure (e.g. a 502
    55	        // from a downstream service) should be retryable, not locked in.
    56	        if (res.statusCode < 400) {
    57	          void redis
    58	            .set(cacheKey, JSON.stringify({ status: res.statusCode, body }), 'EX', TTL_SECONDS)
    59	            .catch((err) => logger.error({ cacheKey, err }, 'Failed to cache idempotent response'));
    60	        }
    61	        return originalJson(body);
    62	      };
    63	
    64	      next();
    65	    })
    66	    .catch((err) => {
    67	      // Redis being unavailable shouldn't take down checkout/uploads —
    68	      // fail open (process the request normally, just without dedup).
    69	      logger.error({ cacheKey, err }, 'Idempotency cache lookup failed, proceeding without it');
    70	      next();
    71	    });
    72	}

