   214	/**
   215	 * GET /api/deployments/:id/logs/stream
   216	 * Streams real-time logs from a deployment using Server-Sent Events (SSE).
   217	 * 
   218	 * Requirements:
   219	 * - Requirement 19.4: Support log streaming for real-time log viewing
   220	 * - Stream container stdout and stderr to API clients
   221	 * - Display timestamps with each log line
   222	 * - RBAC: deployment owner or admin/dev can stream logs
   223	 * 
   224	 * The endpoint proxies the SSE stream from the node-agent to the client,
   225	 * handling connection cleanup when the client disconnects.
   226	 */
   227	deploymentsRouter.get('/deployments/:id/logs/stream', async (req: AuthedRequest, res) => {
   228	  const deployment = await loadOwnedDeployment(req, req.params.id);
   229	  if (!deployment) return res.status(404).json({ error: 'Deployment not found' });
   230	  if (!deployment.containerId) {
   231	    // No container means nothing to stream
   232	    res.setHeader('Content-Type', 'text/event-stream');
   233	    res.setHeader('Cache-Control', 'no-cache');
   234	    res.setHeader('Connection', 'keep-alive');
   235	    res.write('data: {"type":"error","message":"No container running for this deployment"}\n\n');
   236	    return res.end();
   237	  }
   238	
   239	  // Set up SSE headers
   240	  res.setHeader('Content-Type', 'text/event-stream');
   241	  res.setHeader('Cache-Control', 'no-cache');
   242	  res.setHeader('Connection', 'keep-alive');
   243	  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering
   244	
   245	  // Build the node-agent stream URL
   246	  const streamUrl = `http://${deployment.node.ip}:${env.nodeAgentPort}/agent/deployments/${deployment.containerId}/logs/stream`;
   247	  
   248	  try {
   249	    // Fetch the stream from node-agent
   250	    const nodeResponse = await fetch(streamUrl, {
   251	      headers: {
   252	        'x-agent-secret': env.nodeAgentSecret,
   253	      },
   254	    });
   255	
   256	    if (!nodeResponse.ok) {
   257	      res.write(`data: ${JSON.stringify({type:"error",message:"Failed to connect to log stream"})}\n\n`);
   258	      return res.end();
   259	    }
   260	
   261	    if (!nodeResponse.body) {
   262	      res.write(`data: ${JSON.stringify({type:"error",message:"No stream body from node"})}\n\n`);
   263	      return res.end();
   264	    }
   265	
   266	    // Pipe the stream from node-agent to client
   267	    const reader = nodeResponse.body.getReader();
   268	    const decoder = new TextDecoder();
   269	
   270	    const streamLogs = async () => {
   271	      try {
   272	        while (true) {
   273	          const { done, value } = await reader.read();
   274	          if (done) break;
   275	          
   276	          // Forward the SSE data directly to the client
   277	          const chunk = decoder.decode(value, { stream: true });
   278	          res.write(chunk);
   279	        }
   280	        res.end();
   281	      } catch (err) {
   282	        logger.error({ deploymentId: deployment.id, err }, 'Error streaming logs from node');
   283	        res.end();
   284	      }
   285	    };
   286	
   287	    // Start streaming
   288	    streamLogs();
   289	
   290	    // Handle client disconnect
   291	    req.on('close', () => {
   292	      logger.info({ deploymentId: deployment.id }, 'Client disconnected from log stream');
   293	      reader.cancel();
   294	      res.end();
   295	    });
   296	
   297	  } catch (err) {
   298	    logger.error({ deploymentId: deployment.id, err }, 'Failed to establish log stream');
   299	    res.write(`data: ${JSON.stringify({type:"error",message:"Failed to establish log stream"})}\n\n`);
   300	    res.end();
   301	  }
   302	});
