   230	  if (!deployment.containerId) {
   231	    // No container means nothing to stream
   232	    res.setHeader('Content-Type', 'text/event-stream');
   233	    res.setHeader('Cache-Control', 'no-cache');
   234	    res.setHeader('Connection', 'keep-alive');
   235	    res.write('data: {"type":"error","message":"No container running for this deployment"}\n\n');
