    const logs = await getLogs(req.params.containerId, Number(req.query.tail) || 200);
    res.json({ logs });
  } catch (err) {
    logger.error({ containerId: req.params.containerId, err }, 'Failed to fetch logs');
    res.status(500).json({ error: 'Failed to fetch logs' });
  }
});
