   196	function parseCsvLine(line) {
   197	  const result = [];
   198	  let current = '';
   199	  let inQuotes = false;
   200	  for (let i = 0; i < line.length; i++) {
   201	    if (line[i] === '"') {
   202	      if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
   203	      else inQuotes = !inQuotes;
   204	    } else if (line[i] === ',' && !inQuotes) {
   205	      result.push(current);
   206	      current = '';
   207	    } else {
   208	      current += line[i];
   209	    }
   210	  }
   211	  result.push(current);
   212	  return result;
   213	}
