{"returncode":0,"stdout":"     1	/**
     2	 * cockpit.js — Node Agent System Management & Security Module (Cockpit-style)
     3	 * 
     4	 * Provides secure system monitoring, systemd service management, Linux user admin,
     5	 * Docker container operations, and UFW firewall rule configuration.
     6	 * 
     7	 * SECURITY DIRECTIVE:
     8	 * All commands are executed strictly via child_process.execFile / spawn with argument arrays.
     9	 * User inputs are sanitized using strict regex validation before reaching execFile.
    10	 */
    11	
    12	const { execFile } = require('child_process');
    13	const util = require('util');
    14	const fs = require('fs/promises');
    15	const si = require('systeminformation');
    16	const Docker = require('dockerode');
    17	
    18	const execFileAsync = util.promisify(execFile);
    19	const docker = new Docker();
    20	
    21	// Validation Whitelists
    22	const REGEX_SERVICE_NAME = /^[a-zA-Z0-9_\-\.]+\.service$|^[a-zA-Z0-9_\-\.]+$/;
    23	const REGEX_USERNAME = /^[a-zA-Z0-9_-]{1,32}$/;
    24	const REGEX_GROUPNAME = /^[a-zA-Z0-9_-]{1,32}$/;
    25	
    26	// ── 1. SYSTEM MONITORING ───────────────────────────────────────────────────
    27	
    28	async function getSystemMonitoringInfo() {
    29	  const [cpu, mem, load, fsSize, time] = await Promise.all([
    30	    si.cpu(),
    31	    si.mem(),
    32	    si.currentLoad(),
    33	    si.fsSize(),
    34	    si.time(),
    35	  ]);
    36	
    37	  return {
    38	    uptimeSeconds: time.uptime,
    39	    loadAverage: load.currentLoad,
    40	    cpu: {
    41	      manufacturer: cpu.manufacturer,
    42	      brand: cpu.brand,
    43	      cores: cpu.cores,
    44	      usagePct: Math.round(load.currentLoad * 100) / 100,
    45	    },
    46	    memory: {
    47	      totalMb: Math.round(mem.total / 1024 / 1024),
    48	      usedMb: Math.round(mem.used / 1024 / 1024),
    49	      freeMb: Math.round(mem.free / 1024 / 1024),
    50	      usedPct: Math.round((mem.used / mem.total) * 10000) / 100,
    51	    },
    52	    disks: fsSize.map((disk) => ({
    53	      fs: disk.fs,
    54	      type: disk.type,
    55	      sizeGb: Math.round(disk.size / 1024 / 1024 / 1024),
    56	      usedGb: Math.round(disk.used / 1024 / 1024 / 1024),
    57	      usedPct: Math.round(disk.use * 100) / 100,
    58	      mount: disk.mount,
    59	    })),
    60	  };
    61	}
    62	
    63	// ── 2. SYSTEMD SERVICE MANAGEMENT ──────────────────────────────────────────
    64	
    65	async function listSystemdServices() {
    66	  try {
    67	    const { stdout } = await execFileAsync('systemctl', [
    68	      'list-units',
    69	      '--type=service',
    70	      '--all',
    71	      '--no-legend',
    72	      '--no-pager',
    73	    ]);
    74	
    75	    const lines = stdout.split('\n');
    76	    const services = [];
    77	
    78	    for (const line of lines) {
    79	      const parts = line.trim().split(/\s+/);
    80	      if (parts.length >= 4) {
    81	        const name = parts[0];
    82	        const load = parts[1];
    83	        const active = parts[2];
    84	        const sub = parts[3];
    85	        const description = parts.slice(4).join(' ');
    86	
    87	        if (name.endsWith('.service')) {
    88	          services.push({
    89	            name,
    90	            status: active === 'active' ? 'active' : sub === 'failed' ? 'failed' : 'inactive',
    91	            loadState: load,
    92	            subState: sub,
    93	            description,
    94	          });
    95	        }
    96	      }
    97	    }
    98	
    99	    return services;
   100	  } catch (err) {
   101	    // Return empty list if systemctl isn't available (e.g., inside container or Windows host)
   102	    return [];
   103	  }
   104	}
   105	
   106	async function controlSystemdService(action, serviceName) {
   107	  const allowedActions = ['start', 'stop', 'restart', 'enable', 'disable'];
   108	  if (!allowedActions.includes(action)) {
   109	    throw new Error(`Invalid service action: ${action}`);
   110	  }
   111	
   112	  if (!REGEX_SERVICE_NAME.test(serviceName)) {
   113	    throw new Error('Invalid service name formatting');
   114	  }
   115	
   116	  const cleanName = serviceName.endsWith('.service') ? serviceName : `${serviceName}.service`;
   117	  await execFileAsync('systemctl', [action, cleanName]);
   118	  return { ok: true, action, service: cleanName };
   119	}
   120	
   121	async function getServiceLogs(serviceName, linesCount = 100) {
   122	  if (!REGEX_SERVICE_NAME.test(serviceName)) {
   123	    throw new Error('Invalid service name formatting');
   124	  }
   125	
   126	  const cleanName = serviceName.endsWith('.service') ? serviceName : `${serviceName}.service`;
   127	  const count = Math.min(Math.max(1, linesCount), 500);
   128	
   129	  const { stdout } = await execFileAsync('journalctl', [
   130	    '-u',
   131	    cleanName,
   132	    '-n',
   133	    String(count),
   134	    '--no-pager',
   135	  ]);
   136	
   137	  return { service: cleanName, logs: stdout };
   138	}
   139	
   140	// ── 3. LINUX USER MANAGEMENT ───────────────────────────────────────────────
   141	
   142	async function listLinuxUsers() {
   143	  try {
   144	    const passwdContent = await fs.readFile('/etc/passwd', 'utf8');
   145	    const lines = passwdContent.split('\n');
   146	    const users = [];
   147	
   148	    for (const line of lines) {
   149	      if (!line.trim() || line.startsWith('#')) continue;
   150	      const parts = line.split(':');
   151	      if (parts.length >= 7) {
   152	        const username = parts[0];
   153	        const uid = parseInt(parts[2], 10);
   154	        const gid = parseInt(parts[3], 10);
   155	        const gecos = parts[4];
   156	        const home = parts[5];
   157	        const shell = parts[6];
   158	
   159	        if (uid >= 1000 || username === 'root') {
   160	          users.push({ username, uid, gid, gecos, home, shell });
   161	        }
   162	      }
   163	    }
   164	
   165	    return users;
   166	  } catch (err) {
   167	    return [];
   168	  }
   169	}
   170	
   171	async function createLinuxUser(username, password) {
   172	  if (!REGEX_USERNAME.test(username)) {
   173	    throw new Error('Invalid username. Must be 1-32 alphanumeric characters, dashes, or underscores.');
   174	  }
   175	
   176	  await execFileAsync('useradd', ['-m', '-s', '/bin/bash', username]);
   177	
   178	  if (password) {
   179	    // Await the password setting instead of fire-and-forget (Bug 3 fix)
   180	    await new Promise((resolve, reject) => {
   181	      const child = execFile('passwd', [username], (err, _stdout, stderr) => {
   182	        if (err) return reject(new Error(stderr || err.message));
   183	        resolve(undefined);
   184	      });
   185	      child.stdin.write(`${password}\n${password}\n`);
   186	      child.stdin.end();
   187	    });
   188	  }
   189	
   190	  return { ok: true, username };
   191	}
   192	
   193	async function deleteLinuxUser(username, removeHome = true) {
   194	  if (!REGEX_USERNAME.test(username)) {
   195	    throw new Error('Invalid username');
   196	  }
   197	
   198	  const args = removeHome ? ['-r', username] : [username];
   199	  await execFileAsync('userdel', args);
   200	  return { ok: true, username };
   201	}
   202	
   203	async function setLinuxUserPassword(username, password) {
   204	  if (!REGEX_USERNAME.test(username)) {
   205	    throw new Error('Invalid username');
   206	  }
   207	
   208	  return new Promise((resolve, reject) => {
   209	    const child = execFile('passwd', [username], (err, stdout, stderr) => {
   210	      if (err) return reject(new Error(stderr || err.message));
   211	      resolve({ ok: true, username });
   212	    });
   213	
   214	    child.stdin.write(`${password}\n${password}\n`);
   215	    child.stdin.end();
   216	  });
   217	}
   218	
   219	async function modifyLinuxUserGroups(username, group, action = 'add') {
   220	  if (!REGEX_USERNAME.test(username) || !REGEX_GROUPNAME.test(group)) {
   221	    throw new Error('Invalid username or group name');
   222	  }
   223	
   224	  if (action === 'add') {
   225	    await execFileAsync('usermod', ['-aG', group, username]);
   226	  } else if (action === 'remove') {
   227	    await execFileAsync('gpasswd', ['-d', username, group]);
   228	  }
   229	
   230	  return { ok: true, username, group, action };
   231	}
   232	
   233	// ── 4. DOCKER CONTAINER MANAGEMENT ─────────────────────────────────────────
   234	
   235	async function listDockerContainers() {
   236	  try {
   237	    const containers = await docker.listContainers({ all: true });
   238	    return containers.map((c) => ({
   239	      id: c.Id,
   240	      shortId: c.Id.slice(0, 12),
   241	      names: c.Names.map((n) => n.replace(/^\//, '')),
   242	      image: c.Image,
   243	      status: c.Status,
   244	      state: c.State, // 'running' | 'exited' | 'paused'
   245	      created: c.Created,
   246	      ports: c.Ports.map((p) => ({
   247	        privatePort: p.PrivatePort,
   248	        publicPort: p.PublicPort,
   249	        type: p.Type,
   250	      })),
   251	    }));
   252	  } catch (err) {
   253	    return [];
   254	  }
   255	}
