    16	 * account) aren't subscriptions. If it's monthly/yearly, creates a new
    17	 * Subscription or extends an existing one for the same order item (the
    18	 * "renew by buying it again" model — see billingRules.computeRenewedPeriodEnd
    19	 * for why renewing early stacks remaining time instead of wasting it).
    20	 */
    21	export async function activateOrExtendSubscription(orderItemId: string): Promise<void> {
