    36	    : orderItem.plan?.billingType) as 'monthly' | 'yearly';
    37	  const existing = await prisma.subscription.findUnique({ where: { orderItemId } });
    38	
    39	  if (existing) {
    40	    const newPeriodEnd = computeRenewedPeriodEnd(existing.currentPeriodEnd, billingPeriod);
    41	    await prisma.subscription.update({
    42	      where: { id: existing.id },
    43	      data: { currentPeriodEnd: newPeriodEnd, status: 'active', pastDueAt: null },
    44	    });
    45	  } else {
    46	    await prisma.subscription.create({
    47	      data: {
    48	        userId: orderItem.order.userId,
    49	        orderItemId,
    50	        currentPeriodEnd: new Date(Date.now() + periodLengthMs(billingPeriod)),
    51	      },
    52	    });
    53	  }
    54	}
