    22	  const orderItem = await prisma.orderItem.findUnique({
    23	    where: { id: orderItemId },
    24	    include: { service: true, plan: true, order: true },
    25	  });
    26	  if (!orderItem) return;
    27	  const isOneTime = orderItem.service
    28	    ? orderItem.service.billingPeriod === 'one_time'
    29	    : orderItem.plan
    30	      ? orderItem.plan.billingType === 'one_time'
    31	      : true;
    32	  if (isOneTime) return;
    33	
    34	  const billingPeriod = (orderItem.service
    35	    ? orderItem.service.billingPeriod
    36	    : orderItem.plan?.billingType) as 'monthly' | 'yearly';
    37	  const existing = await prisma.subscription.findUnique({ where: { orderItemId } });
    38	
    39	  if (existing) {
    40	    const newPeriodEnd = computeRenewedPeriodEnd(existing.currentPeriodEnd, billingPeriod);
    41	    await prisma.subscription.update({
    42	      where: { id: existing.id },
    43	      data: { currentPeriodEnd: newPeriodEnd, status: 'active', pastDueAt: null },
    44	    });
