     3	const DAY_MS = 24 * 60 * 60 * 1000;
     4	
     5	/**
     6	 * How long one billing period is, in milliseconds. Deliberately simple
     7	 * (30/365 days rather than calendar months/years) so renewal math is
     8	 * trivially testable and never lands on an ambiguous date like Feb 30.
     9	 */
    10	export function periodLengthMs(billingPeriod: 'monthly' | 'yearly'): number {
    11	  return billingPeriod === 'monthly' ? 30 * DAY_MS : 365 * DAY_MS;
    12	}
    13	
    14	/**
    15	 * Computes the new currentPeriodEnd when a customer renews. Extends from
    16	 * whichever is LATER: now, or the existing expiry. Renewing early (before
    17	 * expiry) stacks on top of the remaining time rather than wasting it;
    18	 * renewing late (after a lapse) starts fresh from now rather than trying to
    19	 * "back-date" a period that's already elapsed.
    20	 */
    21	export function computeRenewedPeriodEnd(
    22	  currentPeriodEnd: Date,
    23	  billingPeriod: 'monthly' | 'yearly',
    24	  now: Date = new Date()
    25	): Date {
    26	  const base = currentPeriodEnd.getTime() > now.getTime() ? currentPeriodEnd.getTime() : now.getTime();
    27	  return new Date(base + periodLengthMs(billingPeriod));
    28	}
    29	
    30	export type SubscriptionSweepAction = 'none' | 'mark_past_due' | 'cancel';
    31	
    32	/**
    33	 * Decides what should happen to an active/past_due subscription right now,
    34	 * given when its period ended (or, if already past_due, when it became so).
    35	 * Used by the daily sweep (lib/billing.ts's runBillingChecks) — kept as a
    36	 * pure function so the grace-period math can be unit tested without a
    37	 * database.
    38	 * 
    39	 * @param gracePeriodDays - Number of days to wait after period end before cancelling (default from env.gracePeriodDays)
    40	 */
    41	export function decideSweepAction(
    42	  status: 'active' | 'past_due' | 'cancelled',
    43	  currentPeriodEnd: Date,
    44	  pastDueAt: Date | null,
    45	  now: Date = new Date(),
    46	  gracePeriodDays: number = env.gracePeriodDays
    47	): SubscriptionSweepAction {
    48	  if (status === 'cancelled') return 'none';
    49	
    50	  if (status === 'active') {
    51	    return currentPeriodEnd.getTime() <= now.getTime() ? 'mark_past_due' : 'none';
    52	  }
    53	
    54	  // status === 'past_due': cancel once the grace period has elapsed.
    55	  const graceDeadline = (pastDueAt?.getTime() ?? currentPeriodEnd.getTime()) + gracePeriodDays * DAY_MS;
    56	  return now.getTime() >= graceDeadline ? 'cancel' : 'none';
    57	}
