{"returncode":0,"stdout":"     1	export interface ExtractedPayment {
     2	  amount?: number;
     3	  reference?: string;
     4	  source?: string;
     5	  /** Self-reported extraction confidence from Gemini/OCR, 0-100. */
     6	  extractionConfidence?: number;
     7	}
     8	
     9	export interface MatchTarget {
    10	  expectedAmount: number; // smallest currency unit, same scale as Order.total
    11	}
    12	
    13	export type PaymentDecision = 'auto_approved' | 'manual_review' | 'rejected';
    14	
    15	export interface MatchResult {
    16	  confidenceScore: number; // 0-100
    17	  decision: PaymentDecision;
    18	  reasons: string[];
    19	}
    20	
    21	const AUTO_APPROVE_THRESHOLD = 90;
    22	const MANUAL_REVIEW_THRESHOLD = 60;
    23	
    24	/**
    25	 * Scores how well an extracted payment proof matches the order it's meant
    26	 * to be paying for, then routes it per your original design:
    27	 *   >=90  -> auto_approved
    28	 *   60-89 -> manual_review
    29	 *   <60   -> rejected
    30	 *
    31	 * The score blends three signals so no single weak signal can force a wrong
    32	 * auto-approval: how closely the amount matches, whether a plausible
    33	 * reference/transaction ID was found, and how confident the extraction step
    34	 * itself was (a perfectly matching amount read off a blurry, half-guessed
    35	 * image still shouldn't auto-approve).
    36	 */
    37	export function scorePayment(
    38	  extracted: ExtractedPayment,
    39	  target: MatchTarget
    40	): MatchResult {
    41	  const reasons: string[] = [];
    42	
    43	  const amountScore = scoreAmount(extracted.amount, target.expectedAmount, reasons);
    44	  const referenceScore = scoreReference(extracted.reference, reasons);
    45	  const extractionScore = clamp(extracted.extractionConfidence ?? 50, 0, 100);
    46	
    47	  const confidenceScore = Math.round(
    48	    amountScore * 0.5 + extractionScore * 0.3 + referenceScore * 0.2
    49	  );
    50	
    51	  let decision: PaymentDecision = 'rejected';
    52	  if (confidenceScore >= AUTO_APPROVE_THRESHOLD) decision = 'auto_approved';
    53	  else if (confidenceScore >= MANUAL_REVIEW_THRESHOLD) decision = 'manual_review';
    54	
    55	  return { confidenceScore, decision, reasons };
    56	}
    57	
    58	function scoreAmount(
    59	  extractedAmount: number | undefined,
    60	  expectedAmount: number,
    61	  reasons: string[]
    62	): number {
    63	  if (extractedAmount === undefined || expectedAmount <= 0) {
    64	    reasons.push('No amount could be extracted');
    65	    return 0;
    66	  }
    67	
    68	  const diff = Math.abs(extractedAmount - expectedAmount);
    69	  const pctDiff = diff / expectedAmount;
    70	
    71	  if (pctDiff === 0) {
    72	    reasons.push('Amount matches exactly');
    73	    return 100;
    74	  }
    75	  if (pctDiff <= 0.01) {
    76	    reasons.push('Amount matches within rounding tolerance');
    77	    return 95;
    78	  }
    79	  if (pctDiff <= 0.05) {
    80	    reasons.push('Amount is close but not exact (within 5%)');
    81	    return 65;
    82	  }
    83	
    84	  reasons.push(
    85	    `Amount mismatch: expected ${expectedAmount}, got ${extractedAmount}`
    86	  );
    87	  return 0;
    88	}
    89	
    90	function scoreReference(reference: string | undefined, reasons: string[]): number {
    91	  if (!reference || reference.trim().length < 3) {
    92	    reasons.push('No usable transaction reference found');
    93	    return 35; // weak supporting evidence, not disqualifying on its own
    94	  }
    95	  reasons.push('Transaction reference present');
    96	  return 100;
    97	}
    98	
    99	function clamp(value: number, min: number, max: number): number {
   100	  return Math.max(min, Math.min(max, value));
   101	}
