{"returncode":0,"stdout":"     1	import { Router } from 'express';
     2	import { z } from 'zod';
     3	import { prisma } from '../lib/prisma';
     4	import { env } from '../env';
     5	import { parseSms } from '../lib/smsParser';
     6	import { scorePayment } from '../lib/paymentMatcher';
     7	import { verifySmsSignature } from '../lib/smsSignature';
     8	import { notifyAdmins } from '../lib/notifications';
     9	import { notifyDiscordChannel } from '../lib/discordWebhooks';
    10	import { smsWebhookLimiter } from '../middleware/rateLimit';
    11	
    12	export const smsRouter = Router();
    13	
    14	const incomingSmsSchema = z.object({ text: z.string().min(1) });
    15	
    16	smsRouter.post('/sms/incoming', smsWebhookLimiter, async (req, res) => {
    17	  if (!verifySmsSignature(req, env.smsWebhookSecret)) {
    18	    return res.status(401).json({ error: 'Invalid signature' });
    19	  }
    20	
    21	  const parsed = incomingSmsSchema.safeParse(req.body);
    22	  if (!parsed.success) {
    23	    return res.status(400).json({ error: parsed.error.flatten() });
    24	  }
    25	
    26	  const { source, amount, reference } = parseSms(parsed.data.text);
    27	
    28	  const smsEvent = await prisma.smsEvent.create({
    29	    data: {
    30	      source,
    31	      rawText: parsed.data.text,
    32	      parsedJson: { amount, reference },
    33	    },
    34	  });
    35	
    36	  if (amount === undefined) {
    37	    return res.status(202).json({ smsEvent, matched: false, reason: 'No amount parsed' });
    38	  }
    39	
    40	  // Try to match against any pending payment expecting roughly this amount.
    41	  // "Pending" here means the order is awaiting_payment and has no
    42	  // already-approved payment yet.
    43	  const candidates = await prisma.order.findMany({
    44	    where: { status: 'awaiting_payment' },
    45	    include: { payments: true, user: true },
    46	  });
    47	
    48	  let bestMatch: { order: (typeof candidates)[number]; score: number } | null = null;
    49	
    50	  for (const order of candidates) {
    51	    const { confidenceScore, decision } = scorePayment(
    52	      { amount, reference, source, extractionConfidence: 85 }, // SMS text is structured, trust it more than a photo
    53	      { expectedAmount: order.totalLkr }
    54	    );
    55	
    56	    if (decision !== 'rejected' && (!bestMatch || confidenceScore > bestMatch.score)) {
    57	      bestMatch = { order, score: confidenceScore };
    58	    }
    59	  }
    60	
    61	  if (!bestMatch) {
    62	    return res.status(202).json({ smsEvent, matched: false, reason: 'No matching order found' });
    63	  }
    64	
    65	  // IMPORTANT: an SMS match is supporting evidence only, never an approval.
    66	  // Every payment created here lands in manual_review regardless of score —
    67	  // an admin/dev still has to click Approve/Decline on the review queue.
    68	  // Do not reintroduce an auto_approved branch here.
    69	  const payment = await prisma.payment.create({
    70	    data: {
    71	      orderId: bestMatch.order.id,
    72	      method: 'sms',
    73	      extractedJson: { amount, reference, source },
    74	      confidenceScore: bestMatch.score,
    75	      status: 'manual_review',
    76	    },
    77	  });
    78	
    79	  await prisma.smsEvent.update({
    80	    where: { id: smsEvent.id },
    81	    data: { matchedPaymentId: payment.id },
    82	  });
    83	
    84	  void notifyAdmins(
    85	    `SMS payment for order ${bestMatch.order.id} matched (confidence: ${bestMatch.score}%) — awaiting manual admin review.`
    86	  );
    87	  void notifyDiscordChannel('new_payment_submitted', {
    88	    'Order': bestMatch.order.id,
    89	    'Customer': bestMatch.order.user.email,
    90	    'Source': 'SMS forwarder',
    91	    'Match confidence': `${bestMatch.score}%`,
    92	  });
    93	
    94	  res.status(201).json({ smsEvent, matched: true, payment });
    95	});
