     2	
     3	export class CloudflareDnsError extends Error {}
     4	
     5	/**
     6	 * Automates the "add a CNAME record" step for a customer's custom domain,
     7	 * when they're willing to hand over a scoped Cloudflare API token (Zone:DNS
     8	 * Edit permission on just their zone) — an alternative to the manual "copy
     9	 * this CNAME into your registrar" flow in lib/customDomain.ts, for
    10	 * customers whose domain also happens to be on Cloudflare.
    11	 *
    12	 * The token and zone ID are supplied per-request by the customer, not
    13	 * stored — this is a one-time DNS record creation, not an ongoing
    14	 * integration that needs a persisted credential.
    15	 */
    16	export async function createCnameViaCloudflare(params: {
    17	  apiToken: string;
    18	  zoneId: string;
    19	  domain: string;
    20	  target: string;
    21	}): Promise<{ recordId: string }> {
    22	  const res = await fetch(`${CF_API_BASE}/zones/${params.zoneId}/dns_records`, {
    23	    method: 'POST',
    24	    headers: {
    25	      Authorization: `Bearer ${params.apiToken}`,
    26	      'Content-Type': 'application/json',
    27	    },
    28	    body: JSON.stringify({
    29	      type: 'CNAME',
    30	      name: params.domain,
    31	      content: params.target,
    32	      // Not proxied — the platform's own Traefik handles TLS termination
    33	      // and needs to see the real connecting client, and a customer's own
    34	      // Cloudflare proxy in front of it would fight with Let's Encrypt's
    35	      // HTTP-01 challenge unless they specifically configure Full/Strict
    36	      // mode themselves, which isn't something to assume here.
    37	      proxied: false,
    38	      ttl: 300,
    39	    }),
    40	  });
    41	
    42	  const data = (await res.json()) as {
    43	    success: boolean;
    44	    result?: { id: string };
    45	    errors?: Array<{ message: string }>;
    46	  };
    47	
    48	  if (!data.success || !data.result) {
    49	    const message = data.errors?.map((e) => e.message).join('; ') ?? 'Unknown Cloudflare API error';
    50	    throw new CloudflareDnsError(message);
    51	  }
    52	
    53	  return { recordId: data.result.id };
    54	}
    55	
    56	export async function deleteCnameViaCloudflare(params: {
    57	  apiToken: string;
    58	  zoneId: string;
    59	  recordId: string;
    60	}): Promise<void> {
    61	  const res = await fetch(`${CF_API_BASE}/zones/${params.zoneId}/dns_records/${params.recordId}`, {
    62	    method: 'DELETE',
    63	    headers: { Authorization: `Bearer ${params.apiToken}` },
    64	  });
    65	
    66	  if (!res.ok) {
    67	    throw new CloudflareDnsError(`Failed to delete Cloudflare DNS record (${res.status})`);
    68	  }
    69	}
