     1	/**
     2	 * Multi-currency support. Deliberately NOT calling a live FX API on every
     3	 * checkout — that's an external dependency and a point of failure for the
     4	 * single most important transaction in the platform. Instead, a rate is
     5	 * stored (admin-updatable) and snapshotted onto the order at checkout time
     6	 * via `totalLkr`, so a later rate change never retroactively changes what
     7	 * a past order was actually charged.
     8	 *
     9	 * All payment verification (Gemini OCR, SMS matching) works in LKR only —
    10	 * the local banks and mobile-money providers this platform verifies
    11	 * against don't operate in other currencies — so `totalLkr` is what
    12	 * actually gets compared against a payment proof, regardless of what
    13	 * currency the customer saw at checkout.
    14	 */
    15	
    16	export type Currency = 'LKR' | 'USD';
    17	
    18	/**
    19	 * In production this should be admin-configurable and persisted (e.g. a
    20	 * dedicated settings row) rather than hardcoded — this default is a
    21	 * starting point, not a live rate.
    22	 */
    23	const DEFAULT_USD_TO_LKR_RATE = 300;
    24	
    25	export function convertToLkr(amount: number, currency: Currency, usdToLkrRate = DEFAULT_USD_TO_LKR_RATE): number {
    26	  if (currency === 'LKR') return amount;
    27	  return Math.round(amount * usdToLkrRate);
    28	}
    29	
    30	export function formatCurrency(amountInSmallestUnit: number, currency: Currency): string {
    31	  const amount = amountInSmallestUnit / 100;
    32	  const formatted = amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    33	  return currency === 'LKR' ? `LKR ${formatted}` : `$${formatted}`;
    34	}

