     1	export interface ParsedSms {
     2	  source: 'ezcash' | 'combank' | 'sampath' | 'unknown';
     3	  amount?: number;
     4	  reference?: string;
     5	}
     6	
     7	const SOURCE_PATTERNS: Array<{ source: ParsedSms['source']; test: RegExp }> = [
     8	  { source: 'ezcash', test: /ezcash/i },
     9	  { source: 'combank', test: /combank|commercial\s*bank/i },
    10	  { source: 'sampath', test: /sampath/i },
    11	];
    12	
    13	const AMOUNT_PATTERN = /Rs\.?\s?([\d,]+\.\d{2}|[\d,]+)/i;
    14	const REFERENCE_PATTERN = /(?:ref(?:erence)?|txn|transaction)\s*[:#]?\s*([A-Za-z0-9]{4,})/i;
    15	
    16	/**
    17	 * Parses an incoming SMS body (from EzCash/ComBank/Sampath-style payment
    18	 * notifications) into a structured shape the matching engine can compare
    19	 * against a pending order. Unknown formats still return their best-effort
    20	 * amount/reference extraction — the matching engine scores low confidence
    21	 * for missing fields rather than this parser needing to be exhaustive.
    22	 */
    23	export function parseSms(rawText: string): ParsedSms {
    24	  const source =
    25	    SOURCE_PATTERNS.find((p) => p.test.test(rawText))?.source ?? 'unknown';
    26	
    27	  const amountMatch = rawText.match(AMOUNT_PATTERN);
    28	  const amount = amountMatch
    29	    ? Math.round(parseFloat(amountMatch[1].replace(/,/g, '')) * 100) // store as smallest unit
    30	    : undefined;
    31	
    32	  const referenceMatch = rawText.match(REFERENCE_PATTERN);
    33	  const reference = referenceMatch ? referenceMatch[1] : undefined;
    34	
    35	  return { source, amount, reference };
    36	}

