     1	import crypto from 'crypto';
     2	import type { Request } from 'express';
     3	
     4	/**
     5	 * Verifies the HMAC-SHA256 signature sent by the SMS-forwarding device/app,
     6	 * computed over the exact raw request body bytes using the given secret.
     7	 * This is a device endpoint, not a user one — there's no Firebase token
     8	 * here, so this signature is the only thing standing between this route and
     9	 * the internet. Using req.rawBody (captured in index.ts's express.json
    10	 * verify hook) instead of re-stringifying req.body matters: JSON.stringify
    11	 * of a parsed object isn't guaranteed byte-identical to what the sender
    12	 * actually signed.
    13	 */
    14	export function verifySmsSignature(req: Request, secret: string): boolean {
    15	  const signature = req.headers['x-sms-signature'];
    16	  if (typeof signature !== 'string' || !req.rawBody) return false;
    17	
    18	  const expected = crypto.createHmac('sha256', secret).update(req.rawBody).digest('hex');
    19	
    20	  const a = Buffer.from(signature);
    21	  const b = Buffer.from(expected);
    22	  // Constant-time comparison to avoid leaking signature bytes via timing.
    23	  return a.length === b.length && crypto.timingSafeEqual(a, b);
    24	}

