{"returncode":0,"stdout":"     1	import { prisma } from './prisma';
     2	import { env } from '../env';
     3	import { logger } from './logger';
     4	import { encryptSecret } from './secretsVault';
     5	import { notifyDiscordChannel } from './discordWebhooks';
     6	import { notifyCustomer, notifyAdmins } from './notifications';
     7	import { sendSmtpReleaseEmail, getTierFromPlanName, generateDefaultAliases } from './smtpProvisioner';
     8	import { generateLiveKitKeyPair } from './livekit';
     9	import { selectNodeForDeployment } from './nodeSelector';
    10	import { registerLiveKitKey, provisionDatabaseContainer } from './nodeAgentClient';
    11	import crypto from 'crypto';
    12	
    13	/**
    14	 * Fully automated order fulfillment pipeline.
    15	 *
    16	 * Requirements:
    17	 * 1. Non-VPS services (SMTP, LiveKit, Managed DBs, Bot Hosting, AI Subscriptions)
    18	 *    are automatically provisioned and configured immediately upon payment approval.
    19	 * 2. VPS products (VPS, Leaseweb VPS) are NOT auto-provisioned automatically;
    20	 *    instead, a dedicated Discord Webhook alert is sent to team channels for manual setup.
    21	 */
    22	export async function fulfillOrder(orderId: string): Promise<{ success: boolean; fulfilledItems: string[]; manualVpsItems: string[] }> {
    23	  const order = await prisma.order.findUnique({
    24	    where: { id: orderId },
    25	    include: {
    26	      user: true,
    27	      items: {
    28	        include: {
    29	          service: true,
    30	          plan: {
    31	            include: {
    32	              product: true,
    33	            },
    34	          },
    35	        },
    36	      },
    37	    },
    38	  });
    39	
    40	  if (!order) {
    41	    logger.warn({ orderId }, 'fulfillOrder: Order not found');
    42	    return { success: false, fulfilledItems: [], manualVpsItems: [] };
    43	  }
    44	
    45	  const fulfilledItems: string[] = [];
    46	  const manualVpsItems: string[] = [];
    47	
    48	  for (const item of order.items) {
    49	    const productName = (item.plan?.product?.name || item.plan?.name || item.service?.name || '').toLowerCase();
    50	    const productCategory = (item.plan?.product?.category || '').toLowerCase();
    51	
    52	    const isVps =
    53	      productCategory === 'vps' ||
    54	      productCategory === 'vps_plans' ||
    55	      productCategory === 'leaseweb' ||
    56	      productName.includes('vps') ||
    57	      productName.includes('cloud server') ||
    58	      productName.includes('kvm');
    59	
    60	    if (isVps) {
    61	      manualVpsItems.push(item.plan?.name || item.service?.name || 'VPS Plan');
    62	
    63	      // Dispatch urgent Discord Webhook notification to team for manual setup
    64	      void notifyDiscordChannel('vps_assigned', {
    65	        Alert: '🚨 MANUAL VPS PROVISION REQUIRED',
    66	        Order: order.id,
    67	        Customer: order.user.email,
    68	        Plan: item.plan?.name || item.service?.name || 'VPS Server',
    69	        Amount: `LKR ${order.totalLkr}`,
    70	        Note: 'Payment approved. Please provision and assign VPS IP/credentials in Admin Panel.',
    71	      });
    72	
    73	      void notifyAdmins(
    74	        `🚨 Manual VPS Provision Required for Order ${order.id} (${order.user.email}) - Item: ${item.plan?.name || item.service?.name}`
    75	      );
    76	      continue;
    77	    }
    78	
    79	    // 1. Shared SMTP & Mailbox Hosting
    80	    const isSmtp =
    81	      productCategory === 'smtp_hosting' ||
    82	      productCategory === 'smtp' ||
    83	      productName.includes('smtp') ||
    84	      productName.includes('mail');
    85	
    86	    if (isSmtp) {
    87	      const existingAccount = await prisma.smtpAccount.findFirst({
    88	        where: { orderItemId: item.id },
    89	      });
    90	
    91	      if (!existingAccount) {
    92	        try {
    93	          const tier = getTierFromPlanName(item.plan?.name || 'Starter Mail');
    94	          const autoPassword = `Smtp_${Math.random().toString(36).slice(2, 10)}!2026`;
    95	          const username = `mail_${order.user.id.slice(0, 8)}`;
    96	          const smtpHost = `mail.${env.rootDomain}`;
    97	          const webmailUrl = process.env.WEBMAIL_URL || (process.env.NODE_ENV === 'production' ? `https://mail.${env.rootDomain}` : 'http://localhost:3001/email');
    98	          const aliases = generateDefaultAliases(env.rootDomain, tier.maxAliases);
    99	          const credentialRef = encryptSecret(autoPassword, env.secretsEncryptionKey);
   100	
   101	          await prisma.smtpAccount.create({
   102	            data: {
   103	              userId: order.userId,
   104	              orderItemId: item.id,
   105	              postalOrgId: 'shanutechx',
   106	              smtpHost,
   107	              smtpPort: 587,
   108	              smtpUsername: username,
   109	              credentialRef,
   110	              webmailUrl,
   111	            },
   112	          });
   113	
   114	          void sendSmtpReleaseEmail({
   115	            clientEmail: order.user.email,
   116	            clientName: order.user.displayName || order.user.email,
   117	            planName: item.plan?.name || tier.name,
   118	            tier,
   119	            smtpHost,
   120	            smtpPort: 587,
   121	            smtpUsername: username,
   122	            smtpPassword: autoPassword,
   123	            webmailUrl,
   124	            domain: env.rootDomain,
   125	            aliases,
   126	            orderId: order.id,
   127	            paymentId: 'AUTO_PROVISION',
   128	            amountPaid: `LKR ${order.totalLkr}`,
   129	          });
   130	
   131	          fulfilledItems.push(`SMTP Mailbox (${username}@${env.rootDomain})`);
   132	          logger.info({ orderId: order.id, username }, 'Auto-provisioned SMTP Account');
   133	        } catch (err) {
   134	          logger.error({ orderId: order.id, err }, 'Failed to auto-provision SMTP account');
   135	        }
   136	      }
   137	    }
   138	
   139	    // 2. LiveKit WebRTC
   140	    const isLiveKit = productCategory === 'livekit' || productName.includes('livekit');
   141	    if (isLiveKit) {
   142	      const existingLk = await prisma.liveKitProject.findFirst({ where: { orderItemId: item.id } });
   143	      if (!existingLk) {
   144	        try {
   145	          let node;
   146	          try {
   147	            node = await selectNodeForDeployment({ requiredTag: 'livekit', isAdminDeployment: true });
   148	          } catch {
   149	            // fallback node
   150	            node = await prisma.node.findFirst();
   151	          }
   152	
   153	          if (node) {
   154	            const { apiKey, apiSecret } = generateLiveKitKeyPair();
   155	            const apiSecretRef = encryptSecret(apiSecret, env.secretsEncryptionKey);
   156	
   157	            const project = await prisma.liveKitProject.create({
   158	              data: { userId: order.userId, orderItemId: item.id, apiKey, apiSecretRef, nodeId: node.id },
   159	            });
   160	
   161	            try {
   162	              await registerLiveKitKey(node, { apiKey, apiSecret });
   163	            } catch (lkErr) {
   164	              logger.warn({ lkErr }, 'LiveKit key registration on node deferred');
   165	            }
   166	
   167	            fulfilledItems.push(`LiveKit Project (${project.apiKey})`);
   168	            logger.info({ orderId: order.id, apiKey }, 'Auto-provisioned LiveKit Project');
   169	          }
   170	        } catch (err) {
   171	          logger.error({ orderId: order.id, err }, 'Failed to auto-provision LiveKit project');
   172	        }
   173	      }
   174	    }
   175	
   176	    // 3. Managed Database (Postgres / MySQL / Redis / MongoDB)
   177	    const isManagedDb = productCategory === 'managed_database' || productName.includes('database');
   178	    if (isManagedDb) {
   179	      try {
   180	        let dbType: 'postgres' | 'mysql' | 'redis' | 'mongodb' = 'postgres';
   181	        if (productName.includes('mysql')) dbType = 'mysql';
   182	        else if (productName.includes('redis')) dbType = 'redis';
   183	        else if (productName.includes('mongo')) dbType = 'mongodb';
   184	
   185	        const node = await prisma.node.findFirst();
   186	        if (node) {
   187	          const rawPassword = crypto.randomBytes(16).toString('hex');
   188	          const credentialRef = encryptSecret(rawPassword, env.secretsEncryptionKey);
   189	
   190	          const db = await prisma.managedDatabase.create({
   191	            data: { userId: order.userId, nodeId: node.id, type: dbType, status: 'pending', credentialRef },
   192	          });
   193	
   194	          void provisionDatabaseContainer(node, { databaseId: db.id, type: dbType, password: rawPassword })
   195	            .then(async (result) => {
   196	              await prisma.managedDatabase.update({
   197	                where: { id: db.id },
   198	                data: {
   199	                  status: 'running',
   200	                  containerId: result.containerId,
   201	                  internalHost: result.containerName,
   202	                  internalPort: result.internalPort,
   203	                },
   204	              });
   205	            })
   206	            .catch(async () => {
   207	              await prisma.managedDatabase.update({ where: { id: db.id }, data: { status: 'failed' } });
   208	            });
   209	
   210	          fulfilledItems.push(`Managed ${dbType.toUpperCase()} Database`);
   211	        }
   212	      } catch (err) {
   213	        logger.error({ orderId: order.id, err }, 'Failed to auto-provision Managed Database');
   214	      }
   215	    }
   216	
   217	    // 4. AI Subscriptions
   218	    const isAiSub = productCategory === 'ai_subscription' || productName.includes('ai');
   219	    if (isAiSub) {
   220	      fulfilledItems.push(`AI Subscription (${item.plan?.name || 'AI Access'})`);
   221	      void notifyCustomer(
   222	        order.user,
   223	        `Your AI Subscription for order ${order.id} is active! Please visit Support Tickets to access your AI environment credentials.`
   224	      );
   225	    }
   226	  }
   227	
   228	  // Summary Notification to Discord
   229	  if (fulfilledItems.length > 0) {
   230	    void notifyDiscordChannel('payment_approved', {
   231	      Order: order.id,
   232	      Customer: order.user.email,
   233	      AutoProvisioned: fulfilledItems.join(', '),
   234	      Status: 'Auto-Fulfilled',
   235	    });
   236	  }
   237	
   238	  return { success: true, fulfilledItems, manualVpsItems };
   239	}
