   170	export function checkTcpPort(host: string, port: number, timeoutMs = 5000): Promise<CheckResult> {
   171	  const start = Date.now();
   172	  return new Promise((resolve) => {
   173	    const socket = new net.Socket();
   174	    socket.setTimeout(timeoutMs);
   175	
   176	    socket.on('connect', () => {
