   182	    socket.on('timeout', () => {
   183	      const responseTimeMs = Date.now() - start;
   184	      socket.destroy();
   185	      resolve({ isUp: false, responseTimeMs, errorMessage: 'TCP Connection Timed Out' });
   186	    });
