   202	  const start = Date.now();
   203	  return new Promise((resolve) => {
   204	    const socket = tls.connect(port, hostname, { servername: hostname, timeout: timeoutMs }, () => {
   205	      const responseTimeMs = Date.now() - start;
   206	      const cert = socket.getPeerCertificate();
   207	      socket.end();
   208	
   209	      if (!cert || !cert.valid_to) {
