   290	      statusCode = res.status;
   291	      isUp = res.status < 500;
   292	    } catch (err) {
   293	      errorMessage = (err as Error).message;
   294	      logger.warn({ deploymentId: deployment.id, url, err }, 'HTTP Uptime check failed');
   295	    }
   296	
   297	    const responseTimeMs = Date.now() - start;
   298	
   299	    // Check previous check to detect downtime / recovery transition
   300	    const lastCheck = await prisma.uptimeCheck.findFirst({
   301	      where: { deploymentId: deployment.id },
   302	      orderBy: { checkedAt: 'desc' },
   303	    });
   304	
   305	    await prisma.uptimeCheck.create({
   306	      data: { deploymentId: deployment.id, isUp, responseTimeMs, statusCode, errorMessage },
   307	    });
   308	
   309	    if (lastCheck && lastCheck.isUp !== isUp) {
   310	      const stateStr = isUp ? 'RECOVERED (UP)' : 'DOWN';
   311	      const msg = `Alert: Deployment "${deployment.subdomain}" (${url}) is now ${stateStr}. ${errorMessage ? `Reason: ${errorMessage}` : ''}`;
   312	      
   313	      void notifyCustomer(deployment.user, msg);
