   298	
   299	    // Check previous check to detect downtime / recovery transition
   300	    const lastCheck = await prisma.uptimeCheck.findFirst({
   301	      where: { deploymentId: deployment.id },
   302	      orderBy: { checkedAt: 'desc' },
   303	    });
   304	
   305	    await prisma.uptimeCheck.create({
   306	      data: { deploymentId: deployment.id, isUp, responseTimeMs, statusCode, errorMessage },
   307	    });
