   310	      const stateStr = isUp ? 'RECOVERED (UP)' : 'DOWN';
   311	      const msg = `Alert: Deployment "${deployment.subdomain}" (${url}) is now ${stateStr}. ${errorMessage ? `Reason: ${errorMessage}` : ''}`;
