    99	
   100	export interface ProjectAuthTokenPayload {
   101	  sub: string; // ProjectAuthUser.id
   102	  projectId: string;
   103	  email: string;
   104	}
   105	
   106	export function signProjectAuthToken(payload: ProjectAuthTokenPayload): string {
   107	  return jwt.sign(payload, env.projectAuthJwtSecret, { expiresIn: '7d' });
   108	}
   109	
   110	export function verifyProjectAuthToken(token: string): ProjectAuthTokenPayload {
   111	  return jwt.verify(token, env.projectAuthJwtSecret, { algorithms: ['HS256'] }) as ProjectAuthTokenPayload;
