   122	/** Generates a magic-link token, stores only its hash, returns the raw token for the emailed URL. */
   123	export async function createMagicLink(projectId: string, email: string): Promise<string> {
   124	  const rawToken = crypto.randomBytes(32).toString('hex');
   125	  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
   126	
   127	  await prisma.projectMagicLink.create({
   128	    data: {
   129	      projectId,
   130	      email: email.toLowerCase(),
   131	      tokenHash,
   132	      expiresAt: new Date(Date.now() + 15 * 60 * 1000), // 15 minutes
   133	    },
   134	  });
   135	
   136	  return rawToken;
   137	}
   138	
   139	/** Verifies and consumes (single-use) a magic-link token, returning the email it was issued for. */
   140	export async function consumeMagicLink(projectId: string, rawToken: string): Promise<string | null> {
   141	  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
   142	  const link = await prisma.projectMagicLink.findUnique({ where: { tokenHash } });
   143	
   144	  if (!link || link.projectId !== projectId || link.usedAt || link.expiresAt < new Date()) {
   145	    return null;
   146	  }
   147	
   148	  await prisma.projectMagicLink.update({ where: { id: link.id }, data: { usedAt: new Date() } });
   149	  return link.email;
   150	}
