   153	export async function findOrCreateVerifiedUser(projectId: string, email: string) {
   154	  const normalizedEmail = email.toLowerCase();
   155	  const existing = await prisma.projectAuthUser.findUnique({
   156	    where: { projectId_email: { projectId, email: normalizedEmail } },
   157	  });
   158	  if (existing) {
   159	    if (!existing.emailVerified) {
   160	      return prisma.projectAuthUser.update({ where: { id: existing.id }, data: { emailVerified: true, lastLoginAt: new Date() } });
   161	    }
   162	    return prisma.projectAuthUser.update({ where: { id: existing.id }, data: { lastLoginAt: new Date() } });
   163	  }
   164	  return prisma.projectAuthUser.create({
   165	    data: { projectId, email: normalizedEmail, emailVerified: true, lastLoginAt: new Date() },
   166	  });
   167	}
