     5	export interface SmtpServerOptions {
     6	  host: string;
     7	  port: number;
     8	  user: string;
     9	  pass: string;
    10	  secure?: boolean; // true for 465, false for 587/25
    11	  timeoutMs?: number;
    12	}
    13	
    14	export interface MailOptions {
    15	  from: string;
    16	  to: string;
    17	  subject: string;
    18	  html: string;
    19	  text?: string;
    20	}
    21	
    22	/**
    23	 * Tests connection to an SMTP server by performing TCP/TLS handshake, EHLO, and AUTH.
    24	 */
    25	export async function verifySmtpConnection(options: SmtpServerOptions): Promise<{ ok: boolean; message: string; latencyMs: number }> {
    26	  const startTime = Date.now();
    27	  return new Promise((resolve) => {
    28	    const isImplicitTls = options.port === 465 || options.secure === true;
    29	    let socket: net.Socket;
    30	
    31	    const timeout = setTimeout(() => {
    32	      if (socket) socket.destroy();
    33	      resolve({ ok: false, message: 'SMTP connection timed out after 10000ms', latencyMs: Date.now() - startTime });
    34	    }, options.timeoutMs || 10000);
    35	
    36	    const onConnect = () => {
    37	      let buffer = '';
    38	      let step = 0;
    39	
    40	      const send = (data: string) => {
    41	        if (socket.writable) {
    42	          socket.write(data + '\r\n');
    43	        }
    44	      };
    45	
    46	      const handleResponse = (dataBuf: Buffer) => {
    47	        buffer += dataBuf.toString();
    48	        const lines = buffer.split('\r\n');
    49	        buffer = lines.pop() || '';
    50	
    51	        for (const line of lines) {
    52	          if (!line) continue;
    53	          const code = parseInt(line.slice(0, 3), 10);
    54	
    55	          if (step === 0 && (code === 220 || code === 250)) {
    56	            step = 1;
    57	            send(`EHLO shanutechx.platform`);
    58	          } else if (step === 1 && code === 250) {
    59	            if (options.user && options.pass) {
    60	              step = 2;
    61	              const authPlain = Buffer.from(`\0${options.user}\0${options.pass}`).toString('base64');
    62	              send(`AUTH PLAIN ${authPlain}`);
    63	            } else {
    64	              clearTimeout(timeout);
    65	              socket.end();
    66	              resolve({ ok: true, message: 'EHLO successful (No AUTH provided)', latencyMs: Date.now() - startTime });
    67	            }
    68	          } else if (step === 2) {
    69	            clearTimeout(timeout);
    70	            socket.end();
    71	            if (code === 235 || code === 250) {
    72	              resolve({ ok: true, message: 'SMTP Authentication Successful (235 OK)', latencyMs: Date.now() - startTime });
    73	            } else {
    74	              resolve({ ok: false, message: `SMTP Auth Failed: ${line}`, latencyMs: Date.now() - startTime });
    75	            }
    76	          }
    77	        }
    78	      };
    79	
    80	      if (socket instanceof tls.TLSSocket) {
    81	        socket.on('data', handleResponse);
    82	      } else {
    83	        socket.on('data', handleResponse);
    84	      }
    85	    };
    86	
    87	    if (isImplicitTls) {
    88	      socket = tls.connect(options.port, options.host, { rejectUnauthorized: false }, onConnect);
    89	    } else {
    90	      socket = net.createConnection(options.port, options.host, onConnect);
    91	    }
    92	
    93	    socket.on('error', (err) => {
    94	      clearTimeout(timeout);
    95	      resolve({ ok: false, message: `SMTP socket error: ${err.message}`, latencyMs: Date.now() - startTime });
    96	    });
    97	  });
    98	}
