   100	/**
   101	 * Dispatches a real email over SMTP protocol.
   102	 */
   103	export async function sendSmtpEmail(
   104	  options: SmtpServerOptions,
   105	  mail: MailOptions
   106	): Promise<{ ok: boolean; messageId: string; response: string }> {
   107	  return new Promise((resolve, reject) => {
   108	    const isImplicitTls = options.port === 465 || options.secure === true;
   109	    let socket: net.Socket;
   110	    const messageId = `<msg_${Date.now()}_${Math.random().toString(36).slice(2, 8)}@${options.host}>`;
   111	
   112	    const timeout = setTimeout(() => {
   113	      if (socket) socket.destroy();
   114	      reject(new Error('SMTP email transmission timed out after 10000ms'));
   115	    }, options.timeoutMs || 10000);
   116	
   117	    const onConnect = () => {
   118	      let buffer = '';
   119	      let step = 0;
   120	
   121	      const send = (data: string) => {
   122	        if (socket.writable) {
   123	          socket.write(data + '\r\n');
   124	        }
   125	      };
   126	
   127	      const handleResponse = (dataBuf: Buffer) => {
   128	        buffer += dataBuf.toString();
   129	        const lines = buffer.split('\r\n');
   130	        buffer = lines.pop() || '';
   131	
   132	        for (const line of lines) {
   133	          if (!line) continue;
   134	          const code = parseInt(line.slice(0, 3), 10);
   135	
   136	          if (step === 0 && code === 220) {
   137	            step = 1;
   138	            send(`EHLO shanutechx.platform`);
   139	          } else if (step === 1 && code === 250) {
   140	            if (options.user && options.pass) {
   141	              step = 2;
   142	              const authPlain = Buffer.from(`\0${options.user}\0${options.pass}`).toString('base64');
   143	              send(`AUTH PLAIN ${authPlain}`);
   144	            } else {
   145	              step = 3;
   146	              send(`MAIL FROM:<${mail.from}>`);
   147	            }
   148	          } else if (step === 2 && (code === 235 || code === 250)) {
   149	            step = 3;
   150	            send(`MAIL FROM:<${mail.from}>`);
   151	          } else if (step === 3 && code === 250) {
   152	            step = 4;
   153	            send(`RCPT TO:<${mail.to}>`);
   154	          } else if (step === 4 && code === 250) {
   155	            step = 5;
   156	            send(`DATA`);
   157	          } else if (step === 5 && code === 354) {
   158	            step = 6;
   159	            const plainText = mail.text || mail.html.replace(/<[^>]+>/g, '');
   160	            const rawMessage = [
   161	              `From: ${mail.from}`,
   162	              `To: ${mail.to}`,
   163	              `Subject: ${mail.subject}`,
   164	              `Message-ID: ${messageId}`,
   165	              `MIME-Version: 1.0`,
   166	              `Content-Type: text/html; charset=UTF-8`,
   167	              ``,
   168	              mail.html,
   169	              `.`,
   170	            ].join('\r\n');
   171	            send(rawMessage);
   172	          } else if (step === 6 && code === 250) {
   173	            clearTimeout(timeout);
   174	            send('QUIT');
   175	            socket.end();
   176	            resolve({ ok: true, messageId, response: line });
   177	          } else if (code >= 400) {
   178	            clearTimeout(timeout);
   179	            socket.destroy();
   180	            reject(new Error(`SMTP Error [${code}]: ${line}`));
   181	          }
   182	        }
   183	      };
   184	
   185	      socket.on('data', handleResponse);
   186	    };
   187	
   188	    if (isImplicitTls) {
   189	      socket = tls.connect(options.port, options.host, { rejectUnauthorized: false }, onConnect);
   190	    } else {
   191	      socket = net.createConnection(options.port, options.host, onConnect);
   192	    }
   193	
   194	    socket.on('error', (err) => {
   195	      clearTimeout(timeout);
   196	      reject(new Error(`SMTP Transport Error: ${err.message}`));
   197	    });
   198	  });
   199	}
   200	import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
   201	import { spawn, exec } from 'child_process';
