   204	
   205	function getR2Client(): S3Client | null {
   206	  if (!env.r2Endpoint || !env.r2AccessKeyId || !env.r2SecretAccessKey) {
   207	    return null;
   208	  }
   209	  return new S3Client({
   210	    region: 'auto',
   211	    endpoint: env.r2Endpoint,
   212	    credentials: {
   213	      accessKeyId: env.r2AccessKeyId,
   214	      secretAccessKey: env.r2SecretAccessKey,
   215	    },
   216	  });
   217	}
