   219	function getSlot(): 'even' | 'odd' {
   220	  return new Date().getDate() % 2 === 0 ? 'even' : 'odd';
   221	}
   222	
   223	function dumpDatabase(host: string, port: string, user: string, dbName: string, pgDumpEnv: NodeJS.ProcessEnv): Promise<Buffer> {
   224	  return new Promise((resolve, reject) => {
   225	    const pgDump = spawn('pg_dump', ['-h', host, '-p', port, '-U', user, '-d', dbName, '--no-owner', '--no-privileges'], {
   226	      env: pgDumpEnv,
   227	    });
   228	    const gzip = spawn('gzip', [], { stdio: ['pipe', 'pipe', 'pipe'] });
   229	
   230	    const chunks: Buffer[] = [];
   231	    let errOutput = '';
   232	
   233	    pgDump.stdout.pipe(gzip.stdin);
   234	
   235	    pgDump.stderr.on('data', (data) => {
   236	      errOutput += data.toString();
   237	    });
   238	
   239	    gzip.stderr.on('data', (data) => {
   240	      errOutput += data.toString();
   241	    });
   242	
   243	    gzip.stdout.on('data', (chunk) => {
   244	      chunks.push(chunk as Buffer);
   245	    });
   246	
   247	    gzip.on('close', (code) => {
   248	      if (code !== 0) {
   249	        return reject(new Error(`pg_dump/gzip failed with code ${code}: ${errOutput}`));
   250	      }
   251	      resolve(Buffer.concat(chunks));
   252	    });
   253	
   254	    pgDump.on('error', (err) => reject(err));
   255	    gzip.on('error', (err) => reject(err));
   256	  });
   257	}
