   259	/**
   260	 * Dump the main Postgres database and upload the gzipped output to R2 or Free Cloud backup target.
   261	 */
   262	export async function runBackup(): Promise<{ key: string; sizeBytes: number; durationMs: number }> {
   263	  const start = Date.now();
   264	  const slot = getSlot();
   265	  const key = `backups/db-${slot}.sql.gz`;
   266	
   267	  const dbUrl = new URL(env.databaseUrl);
   268	  const pgDumpEnv = {
