   203	 * delay rather than requiring a separate cron job — simpler operationally,
   204	 * at the cost of not catching failures that only show up after the
   205	 * process this ran in has exited (Expo's docs recommend checking receipts
   206	 * up to ~30 min later for full reliability; this checks after 2s, which
   207	 * catches immediate rejections but may miss later-surfacing ones — a
   208	 * proper background job would be the improvement, deliberately not
   209	 * built here without a way to test it against real receipts).
   210	 */
   211	async function checkReceiptsAndCleanup(ticketToToken: Map<string, string>): Promise<void> {
   212	  const receiptIds = Array.from(ticketToToken.keys());
   213	  if (receiptIds.length === 0) return;
   214	
   215	  // Give Expo a moment before asking for receipts — checking immediately
   216	  // is a documented anti-pattern (receipts usually aren't ready yet).
   217	  await new Promise((resolve) => setTimeout(resolve, 2000));
