    62	export async function notifyDiscordChannel(
    63	  event: NotificationEvent,
    64	  payload: Record<string, unknown>
    65	): Promise<void> {
    66	  try {
    67	    const targetUrls: string[] = [];
    68	
    69	    // 1. Unified fallback environment variable (DISCORD_WEBHOOK_URL)
    70	    const unifiedUrl = process.env.DISCORD_WEBHOOK_URL;
    71	    if (unifiedUrl && unifiedUrl.startsWith('http')) {
    72	      targetUrls.push(unifiedUrl);
    73	    }
    74	
    75	    // 2. Per-event DB configs
    76	    const configs = await prisma.discordWebhookConfig.findMany({
    77	      where: { event, isActive: true },
    78	    });
    79	
    80	    for (const c of configs) {
    81	      try {
    82	        const url = decryptSecret(c.webhookUrl, env.secretsEncryptionKey);
    83	        if (url && !targetUrls.includes(url)) {
    84	          targetUrls.push(url);
    85	        }
    86	      } catch (err) {
    87	        logger.warn({ event, configId: c.id, err }, 'Failed to decrypt Discord webhook URL');
    88	      }
    89	    }
    90	
    91	    if (targetUrls.length === 0) return;
    92	
    93	    const embed = buildEmbed(event, payload);
    94	
    95	    await Promise.all(
    96	      targetUrls.map(async (url) => {
    97	        try {
    98	          const res = await fetch(url, {
    99	            method: 'POST',
   100	            headers: { 'Content-Type': 'application/json' },
   101	            body: JSON.stringify({ embeds: [embed] }),
   102	          });
   103	          if (!res.ok) {
   104	            logger.warn({ event, status: res.status }, 'Discord webhook returned non-2xx');
   105	          }
   106	        } catch (err) {
   107	          logger.warn({ event, err }, 'Discord webhook delivery failed');
   108	        }
   109	      })
   110	    );
   111	  } catch (err) {
   112	    logger.warn({ event, err }, 'notifyDiscordChannel failed');
   113	  }
   114	}
