    34	  const parsed = provisionSchema.safeParse(req.body);
    35	  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });
    36	
    37	  if (req.user!.role === 'admin' && !(await canAccessResource(parsed.data.userId, req))) {
    38	    return res.status(404).json({ error: 'Customer not found' });
    39	  }
    40	
    41	  const { password, ...rest } = parsed.data;
    42	  const credentialRef = encryptSecret(password, env.secretsEncryptionKey);
    43	
    44	  const provision = await prisma.vpsProvision.create({
    45	    data: { ...rest, credentialRef, status: 'provisioned', provisionedAt: new Date() },
