   141	  const sub = await prisma.subscription.findUnique({
   142	    where: { id: subscriptionId },
   143	    include: { orderItem: { include: { plan: true } } },
   144	  });
   145	  if (!sub) return;
   146	
   147	  const billingType = sub.orderItem.plan?.billingType ?? 'monthly';
   148	  const daysToAdd: Record<string, number> = {
   149	    one_time: 0,
   150	    monthly: 30,
   151	    quarterly: 90,
   152	    semiannual: 180,
   153	    yearly: 365,
   154	  };
   155	  const days = daysToAdd[billingType] ?? 30;
   156	  const base = sub.currentPeriodEnd > new Date() ? sub.currentPeriodEnd : new Date();
   157	  const newEnd = new Date(base.getTime() + days * 86400000);
