    17	import { executeWorkspaceCleanupJob } from './jobs/workspace-cleanup';
    18	import { logger } from './lib/logger';
    19	
    20	// SSL Certificate Renewal Worker
    21	const sslRenewalWorker = new Worker<SSLRenewalJob>(
    22	  'ssl-renewal',
    23	  async (job) => {
    24	    logger.info({ jobId: job.id }, 'Starting SSL renewal job execution');
    25	    await executeSSLRenewalJob();
    26	  },
    27	  {
    28	    connection: redisConnectionOptions,
    29	    concurrency: 1,
    30	  }
    31	);
    32	
    33	sslRenewalWorker.on('completed', (job) => {
    34	  logger.info({ jobId: job.id }, 'SSL renewal job completed successfully');
    35	});
    36	
    37	sslRenewalWorker.on('failed', (job, err) => {
    38	  logger.error({ jobId: job?.id, err }, 'SSL renewal job failed - will retry in 24 hours');
    39	});
    40	
    41	logger.info('SSL renewal worker started');
    42	
    43	(async () => {
    44	  try {
    45	    await sslRenewalQueue.add(
    46	      'ssl-renewal-check',
    47	      {},
    48	      {
    49	        repeat: { pattern: '0 0 * * *' },
    50	        jobId: 'ssl-renewal-daily',
    51	      }
    52	    );
    53	  } catch (error) {
    54	    logger.error({ msg: 'Failed to schedule SSL renewal job', error: String(error) });
    55	  }
    56	})();
    57	
    58	// Workspace Retention Cleanup Worker (24h retention sweep)
    59	const workspaceCleanupWorker = new Worker<WorkspaceCleanupJob>(
    60	  'workspace-cleanup',
    61	  async (job) => {
    62	    logger.info({ jobId: job.id }, 'Starting 24h workspace retention cleanup sweep');
    63	    const result = await executeWorkspaceCleanupJob();
    64	    logger.info({ jobId: job.id, ...result }, 'Workspace retention cleanup job completed');
    65	  },
    66	  { connection: redisConnectionOptions, concurrency: 1 }
    67	);
    68	
    69	workspaceCleanupWorker.on('failed', (job, err) => {
    70	  logger.error({ jobId: job?.id, err }, 'Workspace cleanup job failed');
    71	});
    72	
    73	(async () => {
    74	  try {
    75	    await workspaceCleanupQueue.add(
    76	      'workspace-cleanup-hourly',
    77	      {},
    78	      {
    79	        repeat: { pattern: '0 * * * *' }, // Every hour
    80	        jobId: 'workspace-cleanup-hourly',
    81	      }
    82	    );
    83	    logger.info({ msg: 'Workspace retention cleanup job scheduled successfully', pattern: '0 * * * *' });
    84	  } catch (error) {
    85	    logger.error({ msg: 'Failed to schedule workspace cleanup job', error: String(error) });
    86	  }
    87	})();
