    90	// self-scheduling pattern as SSL renewal above -- routes/billing.ts's
    91	// POST /billing/run-checks (manual trigger, or external cron with
    92	// BILLING_CRON_SECRET) still works too; this just means the sweep no
    93	// longer depends on either of those being wired up externally.
    94	const billingSweepWorker = new Worker<BillingSweepJob>(
    95	  'billing-sweep',
    96	  async (job) => {
    97	    logger.info({ jobId: job.id }, 'Starting billing sweep job execution');
    98	    const result = await runBillingChecks();
    99	    logger.info({ jobId: job.id, ...result }, 'Billing sweep job completed');
   100	  },
   101	  { connection: redisConnectionOptions, concurrency: 1 }
   102	);
   103	
   104	billingSweepWorker.on('failed', (job, err) => {
   105	  logger.error({ jobId: job?.id, err }, 'Billing sweep job failed - will retry');
   106	});
   107	
   108	(async () => {
   109	  try {
   110	    await billingSweepQueue.add(
   111	      'billing-sweep-daily',
   112	      {},
   113	      {
   114	        repeat: { pattern: '0 1 * * *' }, // Daily at 01:00, after SSL renewal
   115	        jobId: 'billing-sweep-daily',
   116	      }
   117	    );
   118	    logger.info({ msg: 'Billing sweep job scheduled successfully', pattern: '0 1 * * *' });
   119	  } catch (error) {
   120	    logger.error({
   121	      msg: 'Failed to schedule billing sweep job',
   122	      error: error instanceof Error ? error.message : String(error),
   123	    });
   124	  }
   125	})();
