   128	// frequently than the daily jobs above since it's meant to catch
   129	// deployments going down promptly, not just once a day.
   130	const uptimeSweepWorker = new Worker<UptimeSweepJob>(
   131	  'uptime-sweep',
   132	  async (job) => {
   133	    await runUptimeChecks();
   134	  },
   135	  { connection: redisConnectionOptions, concurrency: 1 }
   136	);
