   143	  try {
   144	    await uptimeSweepQueue.add(
   145	      'uptime-sweep-recurring',
   146	      {},
   147	      {
   148	        repeat: { every: 5 * 60 * 1000 }, // Every 5 minutes
   149	        jobId: 'uptime-sweep-recurring',
   150	      }
   151	    );
   152	    logger.info({ msg: 'Uptime sweep job scheduled successfully', interval: '5 minutes' });
   153	  } catch (error) {
   154	    logger.error({
   155	      msg: 'Failed to schedule uptime sweep job',
   156	      error: error instanceof Error ? error.message : String(error),
   157	    });
