     9	
    10	/**
    11	 * Deliberate scoping decision (see architecture plan / delivery notes):
    12	 * standing up a real Woodpecker/GitLab CI/Jenkins instance isn't something
    13	 * to fabricate in this codebase — that's an infra choice for you to make
    14	 * and configure separately. What a PaaS actually needs CI/CD *for*, in
    15	 * practice, is "redeploy automatically when I push to my repo" — that's
    16	 * exactly what this is: a real, working git-push-triggered redeploy,
    17	 * supporting the two most common webhook shapes (GitHub, GitLab).
    18	 */
    19	export const deployWebhooksRouter = Router();
    20	
    21	/**
    22	 * GET /deployments/:id/webhook-info
    23	 * Returns webhook URL and whether a secret has been set, without exposing
    24	 * the secret itself. Used by the DeployWebhookPanel UI.
    25	 */
    26	deployWebhooksRouter.get('/deployments/:id/webhook-info', requireAuth, async (req: AuthedRequest, res) => {
    27	  const deployment = await prisma.deployment.findUnique({ where: { id: req.params.id } });
    28	  if (!deployment) return res.status(404).json({ error: 'Deployment not found' });
    29	  if (!(await canAccessResource(deployment.userId, req))) {
    30	    return res.status(404).json({ error: 'Deployment not found' });
    31	  }
    32	
    33	  const webhookUrl = `/api/deploy-webhooks/${deployment.id}`;
    34	  res.json({
    35	    webhookUrl,
    36	    hasSecret: Boolean(deployment.deployWebhookSecret),
    37	    repoUrl: deployment.repoUrl,
    38	    instructions: {
    39	      github: `In your GitHub repo → Settings → Webhooks → Add webhook: Payload URL = <your API base>${webhookUrl}, Content type = application/json, Secret = (generated below), Events = "Just the push event".`,
    40	      gitlab: `In your GitLab repo → Settings → Webhooks: URL = <your API base>${webhookUrl}, Secret Token = (generated below), Trigger = "Push events".`,
    41	    },
    42	  });
    43	});
    44	
    45	/**
    46	 * Owner or staff only — generates (or rotates) the webhook secret and
    47	 * returns it once, same reveal-once pattern as VPS/SMTP credentials. The
    48	 * caller pastes this into their GitHub/GitLab repo's webhook settings.
    49	 */
    50	deployWebhooksRouter.post('/deployments/:id/webhook-secret', requireAuth, async (req: AuthedRequest, res) => {
    51	  const deployment = await prisma.deployment.findUnique({ where: { id: req.params.id } });
    52	  if (!deployment) return res.status(404).json({ error: 'Deployment not found' });
    53	
    54	  // Phase 15: admin scoped to an assigned customer's deployment.
    55	  if (!(await canAccessResource(deployment.userId, req))) {
    56	    return res.status(404).json({ error: 'Deployment not found' });
    57	  }
    58	  if (!deployment.repoUrl) {
    59	    return res.status(409).json({ error: 'This deployment has no repo to redeploy from' });
    60	  }
    61	
    62	  const secret = crypto.randomBytes(32).toString('hex');
    63	  await prisma.deployment.update({ where: { id: deployment.id }, data: { deployWebhookSecret: secret } });
    64	
    65	  const webhookUrl = `/api/deploy-webhooks/${deployment.id}`;
    66	  res.json({
    67	    secret,
    68	    webhookUrl,
    69	    instructions: {
    70	      github: `Add a webhook in your repo's Settings -> Webhooks: Payload URL = <your API base>${webhookUrl}, Content type = application/json, Secret = the value above, event = "Just the push event".`,
    71	      gitlab: `Add a webhook in your repo's Settings -> Webhooks: URL = <your API base>${webhookUrl}, Secret Token = the value above, trigger = "Push events".`,
    72	    },
    73	  });
    74	});
    75	
    76	deployWebhooksRouter.delete('/deployments/:id/webhook-secret', requireAuth, async (req: AuthedRequest, res) => {
    77	  const deployment = await prisma.deployment.findUnique({ where: { id: req.params.id } });
    78	  if (!deployment) return res.status(404).json({ error: 'Deployment not found' });
    79	  if (!(await canAccessResource(deployment.userId, req))) return res.status(404).json({ error: 'Deployment not found' });
    80	
    81	  await prisma.deployment.update({ where: { id: deployment.id }, data: { deployWebhookSecret: null } });
    82	  res.json({ ok: true });
    83	});
    84	
    85	/**
    86	 * The actual webhook receiver — no platform auth, this is called by
    87	 * GitHub/GitLab's servers, not a logged-in dashboard user. Authenticity is
    88	 * verified via the provider's own signature scheme against the stored
    89	 * per-deployment secret, not a bearer token.
    90	 */
    91	deployWebhooksRouter.post('/deploy-webhooks/:deploymentId', async (req, res) => {
    92	  const deployment = await prisma.deployment.findUnique({
    93	    where: { id: req.params.deploymentId },
    94	    include: { node: true },
