     8	import { pushWorkspaceToShadowRepo } from '../lib/shadowBackup';
     9	import { env } from '../env';
    10	
    11	export const uploadDeploymentsRouter = Router();
    12	
    13	uploadDeploymentsRouter.use(requireAuth);
    14	
    15	const upload = multer({
    16	  limits: { fileSize: 100 * 1024 * 1024 }, // 100MB per upload
    17	});
    18	
    19	function getR2Client(): S3Client | null {
    20	  if (!env.r2Endpoint || !env.r2AccessKeyId || !env.r2SecretAccessKey) return null;
    21	  return new S3Client({
    22	    region: 'auto',
    23	    endpoint: env.r2Endpoint,
    24	    credentials: { accessKeyId: env.r2AccessKeyId, secretAccessKey: env.r2SecretAccessKey },
    25	  });
    26	}
    27	
    28	/**
    29	 * POST /api/deployments/upload
    30	 * Multi-file, directory folder, and zip project deployment upload.
    31	 */
    32	uploadDeploymentsRouter.post('/deployments/upload', upload.array('files', 50), async (req: AuthedRequest, res) => {
    33	  const files = (req.files as Express.Multer.File[]) || [];
    34	  if (files.length === 0) {
    35	    return res.status(400).json({ error: 'No files uploaded. Please upload a zip archive or project files.' });
    36	  }
    37	
    38	  const preferredName = (req.body.preferredName || `upload-app-${Date.now()}`).toLowerCase().replace(/[^a-z0-9-]/g, '-');
    39	  const nodeId = req.body.nodeId;
    40	
    41	  try {
    42	    const node = nodeId
    43	      ? await prisma.node.findUnique({ where: { id: nodeId } })
    44	      : await prisma.node.findFirst({ where: { isActive: true } });
    45	
    46	    if (!node) return res.status(400).json({ error: 'No active deployment node available' });
    47	
    48	    // Key storage path
    49	    const storageKey = `source-uploads/${req.user!.id}/${preferredName}-${Date.now()}.zip`;
    50	    const client = getR2Client();
    51	
    52	    if (!client) {
    53	      return res.status(503).json({ error: 'R2 object storage client is not configured on this server' });
    54	    }
    55	
    56	    // For single zip file uploads, upload directly. For multi-file uploads, upload all files.
    57	    if (files.length === 1 && files[0]?.buffer) {
    58	      await client.send(
    59	        new PutObjectCommand({
    60	          Bucket: env.r2BucketName,
    61	          Key: storageKey,
    62	          Body: files[0].buffer,
    63	          ContentType: files[0].mimetype || 'application/zip',
    64	        })
    65	      );
    66	    } else {
    67	      // Multi-file directory upload: upload each file under the folder key prefix
    68	      await Promise.all(
    69	        files.map((file, idx) => {
    70	          const filePath = file.originalname || `file-${idx}`;
    71	          const itemKey = `source-uploads/${req.user!.id}/${preferredName}-${Date.now()}/${filePath}`;
    72	          return client.send(
    73	            new PutObjectCommand({
    74	              Bucket: env.r2BucketName,
    75	              Key: itemKey,
    76	              Body: file.buffer,
    77	              ContentType: file.mimetype || 'application/octet-stream',
    78	            })
    79	          );
    80	        })
    81	      );
    82	    }
    83	
    84	    const deployment = await prisma.deployment.create({
    85	      data: {
    86	        userId: req.user!.id,
    87	        subdomain: preferredName,
    88	        repoUrl: `zip://${storageKey}`,
    89	        branch: 'main',
    90	        nodeId: node.id,
    91	      },
    92	    });
    93	
    94	    // Trigger shadow backup push for non-Git deployment in background
    95	    void pushWorkspaceToShadowRepo(deployment.id);
    96	
    97	    logger.info({ deploymentId: deployment.id, filesCount: files.length }, 'Created upload deployment');
    98	    res.status(201).json({ ok: true, deployment, uploadedFiles: files.length });
    99	  } catch (err: any) {
   100	    logger.error({ err }, 'Failed to upload deployment files');
   101	    res.status(500).json({ error: err.message || 'Failed to process file upload deployment' });
   102	  }
   103	});
