    33	 */
    34	internalBotRouter.get('/internal/customer-summary', async (req: Request, res: Response) => {
    35	  const phone = typeof req.query.phone === 'string' ? req.query.phone.replace(/[^0-9]/g, '') : '';
    36	  if (!phone) return res.status(400).json({ error: 'Phone number is required' });
    37	
    38	  const user = await prisma.user.findFirst({
    39	    where: {
    40	      OR: [
    41	        { phoneNumber: phone },
    42	        { phoneNumber: `+${phone}` },
    43	        { phoneNumber: { contains: phone } },
    44	      ],
    45	    },
    46	  });
    47	
    48	  if (!user) {
    49	    return res.json({ user: null, deployments: [], tickets: [] });
    50	  }
    51	
    52	  const [deployments, tickets] = await Promise.all([
    53	    prisma.deployment.findMany({
    54	      where: { userId: user.id, status: { in: ['running', 'building', 'stopped'] } },
    55	      select: { id: true, subdomain: true, status: true, customDomain: true },
    56	      take: 10,
    57	    }),
    58	    prisma.ticket.findMany({
    59	      where: { userId: user.id, status: { in: ['open', 'pending'] } },
    60	      select: { id: true, subject: true, status: true, updatedAt: true },
    61	      take: 10,
    62	    }),
    63	  ]);
