    65	  const formattedDeployments = deployments.map((d) => ({
    66	    id: d.id,
    67	    name: d.subdomain ? `${d.subdomain}.${env.rootDomain}` : d.id,
    68	    status: d.status,
    69	    publicUrl: d.customDomain ? `https://${d.customDomain}` : (d.subdomain ? `https://${d.subdomain}.${env.rootDomain}` : null),
    70	  }));
