    97	    id: d.id,
    98	    name: d.subdomain ? `${d.subdomain}.${env.rootDomain}` : d.id,
    99	    status: d.status,
   100	    publicUrl: d.customDomain ? `https://${d.customDomain}` : (d.subdomain ? `https://${d.subdomain}.${env.rootDomain}` : null),
   101	    node: d.node,
   102	  }));
   103	
   104	  res.json({ deployments: formatted });
   105	});
   106	
   107	/**
   108	 * POST /api/internal/review-payment
   109	 * Review manual payment proof (Approve or Decline) right inside Discord
   110	 */
   111	internalBotRouter.post('/internal/review-payment', async (req: Request, res: Response) => {
   112	  const { orderId, approve, reason, reviewedBy } = req.body || {};
   113	  if (!orderId || typeof approve !== 'boolean') {
   114	    return res.status(400).json({ error: 'orderId and approve (boolean) are required' });
   115	  }
   116	
   117	  const order = await prisma.order.findUnique({
   118	    where: { id: orderId },
   119	    include: {
   120	      payments: true,
   121	      user: true,
   122	      items: { include: { plan: { include: { product: true } } } },
   123	    },
   124	  });
   125	
   126	  if (!order || !order.payments || order.payments.length === 0) {
   127	    return res.status(404).json({ error: 'Order or associated payment proof not found' });
   128	  }
   129	
   130	  if (order.status === 'paid' && approve) {
   131	    return res.status(400).json({ error: 'Order is already marked as paid' });
   132	  }
   133	
   134	  const targetPayment = order.payments[0];
   135	  const newOrderStatus = approve ? 'paid' : 'failed';
   136	  const paymentStatus = approve ? 'manually_approved' : 'rejected';
   137	
   138	  await prisma.$transaction([
   139	    prisma.payment.update({
   140	      where: { id: targetPayment.id },
   141	      data: {
   142	        status: paymentStatus,
   143	        reviewedAt: new Date(),
   144	        rejectionReason: approve ? null : reason || 'Declined via Discord review',
   145	      },
   146	    }),
   147	    prisma.order.update({
   148	      where: { id: order.id },
   149	      data: { status: newOrderStatus },
   150	    }),
   151	  ]);
   152	
   153	  if (approve) {
   154	    try {
   155	      await fulfillOrder(order.id);
   156	    } catch (err: any) {
   157	      return res.status(500).json({ error: `Payment approved, but order fulfillment failed: ${err.message}` });
   158	    }
   159	  }
   160	
   161	  // Notify customer of review outcome
   162	  const emailRender = renderPaymentReviewEmail({
   163	    orderId: order.id,
   164	    approved: approve,
   165	    reason: reason || undefined,
   166	  });
   167	
   168	  void notifyCustomer(order.user, emailRender.text);
   169	
   170	  res.json({
   171	    ok: true,
   172	    orderId: order.id,
   173	    status: newOrderStatus,
   174	    reviewedBy: reviewedBy || 'Discord Bot',
   175	  });
   176	});
