     2	import { prisma } from '../lib/prisma';
     3	import { requireAuth, AuthedRequest } from '../middleware/auth';
     4	import { notifyDiscordChannel } from '../lib/discordWebhooks';
     5	import { notifyAdmins } from '../lib/notifications';
     6	
     7	/**
     8	 * AI-subscription checkout items (Gemini Pro, GPT Pro, Lovable, Canva seats,
     9	 * etc.) are never auto-provisioned — see architecture plan section 3.2.
    10	 * The customer's popup has a single "Open Ticket" button; this is what it
    11	 * calls. No free text from the customer — the reason is filled in here.
    12	 */
    13	export const aiSubscriptionRouter = Router();
    14	
    15	aiSubscriptionRouter.use(requireAuth);
    16	
    17	/** Idempotent: calling this twice for the same order item returns the same ticket. */
    18	aiSubscriptionRouter.post('/order-items/:id/ai-subscription-ticket', async (req: AuthedRequest, res) => {
    19	  const orderItem = await prisma.orderItem.findUnique({
    20	    where: { id: req.params.id },
    21	    include: {
    22	      order: { include: { user: true } },
    23	      plan: { include: { product: true } },
    24	      aiSubscriptionRequest: { include: { ticket: true } },
    25	    },
    26	  });
    27	
    28	  if (!orderItem || orderItem.order.userId !== req.user!.id) {
    29	    return res.status(404).json({ error: 'Order item not found' });
    30	  }
    31	  if (!orderItem.plan || orderItem.plan.product.category !== 'ai_subscription') {
    32	    return res.status(400).json({ error: 'This order item is not an AI subscription product' });
    33	  }
    34	
    35	  if (orderItem.aiSubscriptionRequest?.ticket) {
    36	    return res.json({ ticket: orderItem.aiSubscriptionRequest.ticket, alreadyExisted: true });
    37	  }
    38	
    39	  const reason = `AI subscription activation: ${orderItem.plan.name}, order #${orderItem.orderId}`;
    40	
    41	  const ticket = await prisma.ticket.create({
    42	    data: {
    43	      userId: req.user!.id,
    44	      orderId: orderItem.orderId,
    45	      subject: reason,
    46	      status: 'open',
    47	      priority: 'medium',
    48	      messages: {
    49	        create: {
    50	          senderId: req.user!.id,
    51	          senderRole: 'customer',
    52	          body: `Please activate my ${orderItem.plan.name} (${orderItem.plan.product.name}) subscription for order #${orderItem.orderId}.`,
    53	        },
    54	      },
    55	    },
    56	  });
    57	
    58	  await prisma.aiSubscriptionRequest.upsert({
    59	    where: { orderItemId: orderItem.id },
    60	    create: { orderItemId: orderItem.id, ticketId: ticket.id },
    61	    update: { ticketId: ticket.id },
    62	  });
    63	
    64	  void notifyAdmins(`New AI subscription activation request: ${reason}`);
    65	  void notifyDiscordChannel('new_ai_subscription_request', {
    66	    'Order': orderItem.orderId,
    67	    'Customer': orderItem.order.user.email,
    68	    'Plan': orderItem.plan.name,
    69	    'Ticket': ticket.id,
    70	  });
    71	
    72	  res.status(201).json({ ticket, alreadyExisted: false });
    73	});
    74	
    75	/** Lets the popup check whether a ticket already exists before showing "Open Ticket" vs "View Ticket". */
    76	aiSubscriptionRouter.get('/order-items/:id/ai-subscription-ticket', async (req: AuthedRequest, res) => {
    77	  const orderItem = await prisma.orderItem.findUnique({
    78	    where: { id: req.params.id },
    79	    include: { order: true, aiSubscriptionRequest: { include: { ticket: true } } },
    80	  });
    81	  if (!orderItem || orderItem.order.userId !== req.user!.id) {
    82	    return res.status(404).json({ error: 'Order item not found' });
    83	  }
    84	  res.json({ ticket: orderItem.aiSubscriptionRequest?.ticket ?? null });
    85	});
