{"returncode":0,"stdout":"     1	import { Router } from 'express';
     2	import { z } from 'zod';
     3	import crypto from 'crypto';
     4	import { prisma } from '../lib/prisma';
     5	import { requireAuth, requireAdmin, AuthedRequest } from '../middleware/auth';
     6	import { runUptimeChecks } from '../lib/uptimeMonitor';
     7	import { env } from '../env';
     8	
     9	export const statusRouter = Router();
    10	
    11	/**
    12	 * Public — no auth. Aggregates platform-wide incidents (manually posted by
    13	 * an admin) and a rollup of the most recent uptime checks across all
    14	 * public deployments, so a visitor can see "is SHANUTECHX itself healthy"
    15	 * without needing to know about any specific customer's deployment.
    16	 */
    17	statusRouter.get('/status', async (_req, res) => {
    18	  const [incidents, recentChecks] = await Promise.all([
    19	    prisma.statusIncident.findMany({ orderBy: { startedAt: 'desc' }, take: 20 }),
    20	    prisma.uptimeCheck.findMany({ orderBy: { checkedAt: 'desc' }, take: 500 }),
    21	  ]);
    22	
    23	  const latestByDeployment = new Map<string, (typeof recentChecks)[number]>();
    24	  for (const check of recentChecks) {
    25	    if (!latestByDeployment.has(check.deploymentId)) {
    26	      latestByDeployment.set(check.deploymentId, check);
    27	    }
    28	  }
    29	
    30	  const total = latestByDeployment.size;
    31	  const up = [...latestByDeployment.values()].filter((c) => c.isUp).length;
    32	
    33	  res.json({
    34	    overallStatus: total === 0 ? 'unknown' : up === total ? 'operational' : up > 0 ? 'partial_outage' : 'major_outage',
    35	    deploymentsUp: up,
    36	    deploymentsTotal: total,
    37	    incidents,
    38	  });
    39	});
    40	
    41	const createIncidentSchema = z.object({
    42	  title: z.string().min(1),
    43	  body: z.string().min(1),
    44	  severity: z.enum(['minor', 'major', 'critical']).default('minor'),
    45	});
    46	
    47	statusRouter.post('/status/incidents', requireAuth, requireAdmin, async (req: AuthedRequest, res) => {
    48	  const parsed = createIncidentSchema.safeParse(req.body);
    49	  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });
    50	
    51	  const incident = await prisma.statusIncident.create({ data: parsed.data });
    52	  res.status(201).json({ incident });
    53	});
    54	
    55	statusRouter.patch('/status/incidents/:id/resolve', requireAuth, requireAdmin, async (req: AuthedRequest, res) => {
    56	  const incident = await prisma.statusIncident.update({
    57	    where: { id: req.params.id },
    58	    data: { resolvedAt: new Date() },
    59	  });
    60	  res.json({ incident });
    61	});
    62	
    63	/**
    64	 * Runs the uptime check sweep. Same dual-trigger pattern as
    65	 * /api/billing/run-checks: an admin button in the dashboard, or a
    66	 * scheduled job hitting this with a shared secret.
    67	 */
    68	statusRouter.post('/status/run-checks', async (req, res) => {
    69	  const cronSecret = req.headers['x-cron-secret'];
    70	  const isCronAuthed = (() => {
    71	    if (typeof cronSecret !== 'string') return false;
    72	    // Always compare fixed-length HMAC digests to avoid leaking the secret
    73	    // length via a short-circuit length check.
    74	    const submitted = crypto.createHmac('sha256', 'shanutechx-cron-gate').update(cronSecret).digest();
    75	    const expected = crypto.createHmac('sha256', 'shanutechx-cron-gate').update(env.billingCronSecret).digest();
    76	    return crypto.timingSafeEqual(submitted, expected);
    77	  })();
    78	
    79	  if (!isCronAuthed) {
    80	    return requireAuth(req as AuthedRequest, res, async () => {
    81	      const role = (req as AuthedRequest).user?.role;
    82	      if (role !== 'admin' && role !== 'dev') {
    83	        return res.status(403).json({ error: 'Admin or dev access required' });
    84	      }
    85	      const result = await runUptimeChecks();
    86	      res.json(result);
    87	    });
    88	  }
    89	
    90	  const result = await runUptimeChecks();
    91	  res.json(result);
    92	});
    93	
    94	/** Per-deployment uptime history for the owning customer (or admin). */
    95	statusRouter.get('/deployments/:id/uptime', requireAuth, async (req: AuthedRequest, res) => {
    96	  const deployment = await prisma.deployment.findUnique({ where: { id: req.params.id } });
    97	  if (!deployment) return res.status(404).json({ error: 'Not found' });
    98	  if (req.user!.role !== 'admin' && deployment.userId !== req.user!.id) {
    99	    return res.status(404).json({ error: 'Not found' });
   100	  }
   101	
   102	  const checks = await prisma.uptimeCheck.findMany({
   103	    where: { deploymentId: deployment.id },
   104	    orderBy: { checkedAt: 'desc' },
   105	    take: 100,
   106	  });
   107	
   108	  const upCount = checks.filter((c: { isUp: boolean }) => c.isUp).length;
   109	  const uptimePct = checks.length ? Math.round((upCount / checks.length) * 1000) / 10 : null;
   110	
   111	  res.json({ checks, uptimePct });
   112	});
","stderr":""}

