     2	import { z } from 'zod';
     3	import { prisma } from '../lib/prisma';
     4	import { requireAuth, requireStaff, AuthedRequest } from '../middleware/auth';
     5	import { ticketVisibilityWhere, canSeeTicket } from '../middleware/rbac';
     6	import { notifyCustomer, notifyAdmins } from '../lib/notifications';
     7	import { parsePagination } from '../lib/pagination';
     8	import { fireWebhook } from '../lib/webhooks';
     9	
    10	export const ticketsRouter = Router();
    11	
    12	ticketsRouter.use(requireAuth);
    13	
    14	const createTicketSchema = z.object({
    15	  subject: z.string().min(1).max(200),
    16	  message: z.string().min(1),
    17	  orderId: z.string().optional(),
    18	});
    19	
    20	ticketsRouter.post('/tickets', async (req: AuthedRequest, res) => {
    21	  const parsed = createTicketSchema.safeParse(req.body);
    22	  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });
    23	
    24	  const ticket = await prisma.ticket.create({
    25	    data: {
    26	      userId: req.user!.id,
    27	      subject: parsed.data.subject,
    28	      orderId: parsed.data.orderId,
    29	      messages: {
    30	        create: {
    31	          senderId: req.user!.id,
    32	          senderRole: 'customer',
    33	          body: parsed.data.message,
    34	        },
    35	      },
    36	    },
    37	    include: { messages: true },
    38	  });
    39	
    40	  void notifyAdmins(`New support ticket from ${req.user!.email}: "${ticket.subject}"`);
    41	
    42	  res.status(201).json({ ticket });
    43	});
    44	
    45	ticketsRouter.get('/tickets', async (req: AuthedRequest, res) => {
    46	  // Phase 15: admin sees tickets from their assigned customers + anyone
    47	  // still unassigned (so nothing goes unhandled); support/dev unrestricted.
    48	  const where = await ticketVisibilityWhere(req);
    49	  const statusFilter = typeof req.query.status === 'string' ? req.query.status : undefined;
    50	  const { take, skip } = parsePagination(req.query);
    51	
    52	  const filter = { ...where, ...(statusFilter ? { status: statusFilter as any } : {}) };
    53	
    54	  const [tickets, total] = await Promise.all([
    55	    prisma.ticket.findMany({
    56	      where: filter,
    57	      include: { user: true, _count: { select: { messages: true } } },
    58	      orderBy: { updatedAt: 'desc' },
    59	      take,
    60	      skip,
    61	    }),
    62	    prisma.ticket.count({ where: filter }),
    63	  ]);
    64	
    65	  res.json({ tickets, total, take, skip });
    66	});
    67	
    68	async function loadOwnedTicket(req: AuthedRequest, id: string) {
    69	  const ticket = await prisma.ticket.findUnique({
    70	    where: { id },
    71	    include: { messages: { orderBy: { createdAt: 'asc' }, include: { sender: true } }, user: true },
    72	  });
    73	  if (!ticket) return null;
    74	  if (!(await canSeeTicket(ticket.userId, req))) return null;
    75	  return ticket;
    76	}
    77	
    78	ticketsRouter.get('/tickets/:id', async (req: AuthedRequest, res) => {
    79	  const ticket = await loadOwnedTicket(req, req.params.id);
    80	  if (!ticket) return res.status(404).json({ error: 'Ticket not found' });
    81	  res.json({ ticket });
    82	});
    83	
    84	const replySchema = z.object({ body: z.string().min(1) });
    85	
    86	ticketsRouter.post('/tickets/:id/messages', async (req: AuthedRequest, res) => {
    87	  const ticket = await loadOwnedTicket(req, req.params.id);
    88	  if (!ticket) return res.status(404).json({ error: 'Ticket not found' });
    89	
    90	  const parsed = replySchema.safeParse(req.body);
    91	  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });
    92	
    93	  // Stored as 'admin' for ANY staff reply (admin or support) — customers
    94	  // see it labeled "Support" either way; the distinction between admin and
    95	  // support doesn't need to be visible to them, only the access-control
    96	  // logic above needs to know about it.
    97	  const isStaffReply = req.user!.role === 'admin' || req.user!.role === 'support' || req.user!.role === 'dev';
    98	
    99	  const message = await prisma.ticketMessage.create({
   100	    data: {
   101	      ticketId: ticket.id,
   102	      senderId: req.user!.id,
   103	      senderRole: isStaffReply ? 'admin' : 'customer',
   104	      body: parsed.data.body,
   105	    },
   106	  });
   107	
   108	  // A customer replying to a ticket staff had marked "pending" (waiting on
   109	  // the customer) should reopen it; staff replying doesn't change status
   110	  // automatically — they set that explicitly via PATCH.
   111	  if (!isStaffReply && ticket.status === 'pending') {
   112	    await prisma.ticket.update({ where: { id: ticket.id }, data: { status: 'open' } });
   113	  } else {
   114	    await prisma.ticket.update({ where: { id: ticket.id }, data: { updatedAt: new Date() } });
   115	  }
   116	
   117	  if (isStaffReply) {
   118	    void notifyCustomer(ticket.user, `New reply on your ticket "${ticket.subject}".`);
   119	  } else {
   120	    void notifyAdmins(`New reply from ${ticket.user.email} on ticket "${ticket.subject}".`);
   121	  }
   122	
   123	  res.status(201).json({ message });
   124	});
   125	
   126	const updateTicketSchema = z.object({
   127	  status: z.enum(['open', 'pending', 'closed']).optional(),
   128	  priority: z.enum(['low', 'medium', 'high']).optional(),
   129	});
   130	
   131	ticketsRouter.patch('/tickets/:id', requireStaff, async (req: AuthedRequest, res) => {
   132	  const existing = await loadOwnedTicket(req, req.params.id);
   133	  if (!existing) return res.status(404).json({ error: 'Ticket not found' });
   134	
   135	  const parsed = updateTicketSchema.safeParse(req.body);
   136	  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });
   137	
   138	  const ticket = await prisma.ticket.update({
   139	    where: { id: existing.id },
   140	    data: parsed.data,
   141	  });
   142	
   143	  await prisma.auditLog.create({
   144	    data: { adminId: req.user!.id, action: 'ticket.update', target: ticket.id },
   145	  });
   146	  void fireWebhook(ticket.userId, 'ticket_updated', { ticketId: ticket.id, status: ticket.status, priority: ticket.priority });
   147	
   148	  res.json({ ticket });
   149	});
