{"returncode":0,"stdout":"     1	import { Router, Request, Response } from 'express';
     2	import { z } from 'zod';
     3	import { requireAuth, requireAdmin, AuthedRequest } from '../middleware/auth';
     4	import { prisma } from '../lib/prisma';
     5	
     6	/**
     7	 * Knowledge Base. Rewritten (audit finding H1) from module-level `let
     8	 * articles = [...]` / `let categories = [...]` in-memory arrays -- reset
     9	 * to the original seed data on every restart/redeploy, and inconsistent
    10	 * across horizontally-scaled instances -- to real Prisma-backed tables
    11	 * (KbArticle, KbCategory). Behavior and response shapes are unchanged;
    12	 * only the storage layer is different.
    13	 */
    14	
    15	export const knowledgebaseRouter = Router();
    16	
    17	const CATEGORY_SLUGS = ['deployments', 'vps', 'databases', 'domains', 'billing', 'api', 'troubleshooting'] as const;
    18	
    19	function serializeArticle(a: { category: { slug: string } } & Record<string, any>) {
    20	  const { category, categoryId, ...rest } = a;
    21	  return { ...rest, category: category.slug };
    22	}
    23	
    24	// GET /api/knowledgebase - Authenticated: List categories & articles
    25	knowledgebaseRouter.get('/', requireAuth, async (req: Request, res: Response) => {
    26	  const { category, q } = req.query;
    27	
    28	  const where: any = { published: true };
    29	  if (category && typeof category === 'string' && category !== 'all') {
    30	    where.category = { slug: category };
    31	  }
    32	  if (q && typeof q === 'string' && q.trim()) {
    33	    where.OR = [
    34	      { title: { contains: q, mode: 'insensitive' } },
    35	      { summary: { contains: q, mode: 'insensitive' } },
    36	      { content: { contains: q, mode: 'insensitive' } },
    37	    ];
    38	  }
    39	
    40	  const [categories, articles] = await Promise.all([
    41	    prisma.kbCategory.findMany({ orderBy: { name: 'asc' } }),
    42	    prisma.kbArticle.findMany({ where, include: { category: true }, orderBy: { updatedAt: 'desc' } }),
    43	  ]);
    44	
    45	  res.json({
    46	    categories,
    47	    articles: articles.map(serializeArticle),
    48	    total: articles.length,
    49	  });
    50	});
    51	
    52	// GET /api/knowledgebase/articles/:id - Read single article & increment view count
    53	knowledgebaseRouter.get('/articles/:id', requireAuth, async (req: Request, res: Response) => {
    54	  const article = await prisma.kbArticle.findFirst({
    55	    where: { OR: [{ id: req.params.id }, { slug: req.params.id }] },
    56	    include: { category: true },
    57	  });
    58	  if (!article) return res.status(404).json({ error: 'Article not found' });
    59	
    60	  const updated = await prisma.kbArticle.update({
    61	    where: { id: article.id },
    62	    data: { views: { increment: 1 } },
    63	    include: { category: true },
    64	  });
    65	
    66	  res.json({ article: serializeArticle(updated) });
    67	});
    68	
    69	// POST /api/knowledgebase/articles/:id/helpful - Vote article as helpful
    70	knowledgebaseRouter.post('/articles/:id/helpful', requireAuth, async (req: Request, res: Response) => {
    71	  const article = await prisma.kbArticle.findUnique({ where: { id: req.params.id } });
    72	  if (!article) return res.status(404).json({ error: 'Article not found' });
    73	
    74	  const updated = await prisma.kbArticle.update({
    75	    where: { id: req.params.id },
    76	    data: { helpfulCount: { increment: 1 } },
    77	    include: { category: true },
    78	  });
    79	
    80	  res.json({ article: serializeArticle(updated) });
    81	});
