    83	// Admin Schema
    84	const articleSchema = z.object({
    85	  title: z.string().min(3),
    86	  category: z.enum(CATEGORY_SLUGS),
    87	  summary: z.string().min(5),
    88	  content: z.string().min(10),
    89	  published: z.boolean().default(true),
    90	});
    91	
    92	function slugify(title: string): string {
    93	  return title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    94	}
    95	
    96	// POST /api/knowledgebase/articles - Admin: Create article
    97	knowledgebaseRouter.post('/articles', requireAuth, requireAdmin, async (req: AuthedRequest, res: Response) => {
    98	  const parse = articleSchema.safeParse(req.body);
    99	  if (!parse.success) {
   100	    return res.status(400).json({ error: 'Invalid article data', details: parse.error.format() });
   101	  }
   102	
   103	  const category = await prisma.kbCategory.findUnique({ where: { slug: parse.data.category } });
   104	  if (!category) return res.status(400).json({ error: `Unknown category "${parse.data.category}"` });
   105	
   106	  const baseSlug = slugify(parse.data.title);
