   161	 */
   162	vpsPlansRouter.delete('/vps-plans/:id', requireRole('admin', 'dev'), async (req: AuthedRequest, res) => {
   163	  const { id } = req.params;
   164	  try {
   165	    // Check if plan exists
   166	    const existingPlan = await prisma.vpsPlan.findUnique({
   167	      where: { id },
   168	    });
   169	
   170	    if (!existingPlan) {
   171	      return res.status(404).json({ error: 'VPS plan not found', id });
   172	    }
   173	
   174	    // Delete the VPS plan
   175	    await prisma.vpsPlan.delete({
   176	      where: { id },
   177	    });
   178	
   179	    // Log audit event
   180	    await prisma.auditLog.create({
   181	      data: {
   182	        adminId: req.user!.id,
   183	        action: `vps-plan.delete:${id}`,
   184	        target: id,
   185	      },
   186	    });
   187	
   188	    logger.info({ planId: id, userId: req.user!.id }, 'VPS plan deleted');
   189	    return res.json({ success: true, id, deleted: true });
   190	  } catch (err: any) {
   191	    // Audit finding H4: this used to just return a raw 500 here, which
   192	    // directly violated the project's own CLAUDE.md guardrail #2 --
   193	    // VPS Plans are its explicit example of "gracefully set isActive:
   194	    // false rather than crashing with foreign key constraint errors"
   195	    // when historical order references exist. products.ts already
   196	    // implements this correctly; mirroring that pattern here.
   197	    logger.warn(
   198	      { err, planId: id, userId: req.user!.id },
   199	      'Failed to hard-delete VPS plan (likely existing order/provision references) — deactivating instead'
   200	    );
   201	    const deactivated = await prisma.vpsPlan
   202	      .update({ where: { id }, data: { isActive: false } })
   203	      .catch(() => null);
   204	
   205	    if (!deactivated) {
   206	      return res.status(500).json({ error: 'Failed to delete or deactivate VPS plan', details: err.message });
   207	    }
   208	
   209	    await prisma.auditLog.create({
   210	      data: {
   211	        adminId: req.user!.id,
   212	        action: `vps-plan.deactivate:${id}`,
   213	        target: id,
   214	      },
   215	    });
   216	
   217	    return res.json({
   218	      success: true,
   219	      id,
   220	      deactivated: true,
   221	      message: 'VPS plan has existing order history, so it was deactivated instead of hard-deleted.',
   222	    });
   223	  }
   224	});
